DG.put("giaan-prabodh/1",{"n":1,"title":"ਅਥ ਗਿਆਨ ਪ੍ਰਬੋਧ ਗ੍ਰੰਥ ਲਿਖ੍ਯਤੇ।","title_roman":"Ath giaan prabodh granth likhyate |","page":251,"blocks":[{"type":"heading","kind":"chhand","name":"ਭੁਜੰਗ ਪ੍ਰਯਾਤ ਛੰਦ","gurmukhi":"ਭੁਜੰਗ ਪ੍ਰਯਾਤ ਛੰਦ। ਤ੍ਵਪ੍ਰਸਾਦਿ","roman":"Bhujang prayaat chhand | tvaprasaadi","meaning_en":"","page":251,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ"},{"type":"verse","number":[1],"number_text":"੧।","page":251,"lines":[{"gurmukhi":"ਨਮੋ ਨਾਥ ਪੂਰੇ ਸਦਾ ਸਿਧ ਕਰਮੰ। ਅਛੇਦੀ ਅਭੇਦੀ ਸਦਾ ਏਕ ਧਰਮੰ।","roman":"Namo naath poore sadaa sidh karman | achhedee abhedee sadaa ek dharman |","meaning_en":"","page":251},{"gurmukhi":"ਕਲੰਕੰ ਬਿਨਾ ਨਿਹਕਲੰਕੀ ਸਰੂਪੇ। ਅਛੇਦੰ ਅਭੇਦੰ ਅਖੇਦੰ ਅਨੂਪੇ। ੧।","roman":"Kalankan binaa nihaklankee saroope | achhedan abhedan akhedan anoope | 1 |","meaning_en":"","page":251}]},{"type":"verse","number":[2],"number_text":"੨।","page":251,"lines":[{"gurmukhi":"ਨਮੋ ਲੋਕ ਲੋਕੇਸ੍ਵਰੰ ਲੋਕ ਨਾਥੇ। ਸਦੈਵੰ ਸਦਾ ਸਰਬ ਸਾਥੰ ਅਨਾਥੇ।","roman":"Namo lok lokesvaran lok naathe | sadaivan sadaa sarab saathan anaathe |","meaning_en":"","page":251},{"gurmukhi":"ਨੋਮ ਏਕ ਰੂਪੰ ਅਨੇਕੰ ਸਰੂਪੇ। ਸਦਾ ਸਰਬ ਸਾਹੰ ਸਦਾ ਸਰਬ ਭੂਪੇ। ੨।","roman":"Nom ek roopan anekan saroope | sadaa sarab saahan sadaa sarab bhoope | 2 |","meaning_en":"","page":251}]},{"type":"verse","number":[3],"number_text":"੩।","page":251,"lines":[{"gurmukhi":"ਅਛੇਦੰ ਅਭੇਦੰ ਅਨਾਮੰ ਅਠਾਮੰ। ਸਦਾ ਸਰਬਦਾ ਸਿਧਦਾ ਬੁਧਿ ਧਾਮੰ।","roman":"Achhedan abhedan anaaman athaaman | sadaa sarabdaa sidhdaa budhi dhaaman |","meaning_en":"","page":251},{"gurmukhi":"ਅਜੰਤ੍ਰੰ ਅਮੰਤ੍ਰੰ ਅਕੰਤ੍ਰੰ ਅਭਰੰਮੰ। ਅਖੇਦੰ ਅਭੇਦੰ ਅਛੇਦੰ ਅਕਰਮੰ। ੩।","roman":"Ajantran amantran akantran abhranman | akhedan abhedan achhedan akarman | 3 |","meaning_en":"","page":251}]},{"type":"verse","number":[4],"number_text":"੪।","page":251,"lines":[{"gurmukhi":"ਅਗਾਧੇ ਅਬਾਧੇ ਅਗੰਤੰ ਅਨੰਤੰ। ਅਲੇਖੰ ਅਭੇਖੰ ਅਭੂਤੰ ਅਗੰਤੰ।","roman":"Agaadhe abaadhe agantan anantan | alekhan abhekhan abhootan agantan |","meaning_en":"","page":251},{"gurmukhi":"ਨ ਰੰਗੰ ਨ ਰੂਪੰ ਨ ਜਾਤੰ ਨ ਪਾਤੰ। ਨ ਸਤ੍ਰੋ ਨ ਮਿਤ੍ਰੋ ਨ ਪੁਤ੍ਰੋ ਨ ਮਾਤੰ। ੪।","roman":"Na rangan na roopan na jaatan na paatan | na satro na mitro na putro na maatan | 4 |","meaning_en":"","page":251}]},{"type":"verse","number":[5],"number_text":"੫।","page":251,"lines":[{"gurmukhi":"ਅਭੂਤੰ ਅਭੰਗੰ ਅਭਿਖੰ ਭਵਾਨੰ। ਪਰੇਯੰ ਪੁਨੀਤੰ ਪਵਿਤ੍ਰੰ ਪ੍ਰਧਾਨੰ।","roman":"Abhootan abhangan abhikhan bhavaanan | pareyan puneetan pavitran pradhaanan |","meaning_en":"","page":251},{"gurmukhi":"ਅਗੰਜੇ ਅਭੰਜੇ ਅਕਾਮੰ ਅਕਰਮੰ। ਅਨੰਤੇ ਬਿਅੰਤੇ ਅਭੂਮੇ ਅਭਰਮੰ। ੫।","roman":"Aganje abhanje akaaman akarman | anante biante abhoome abharman | 5 |","meaning_en":"","page":251}]},{"type":"verse","number":[6],"number_text":"੬।","page":251,"lines":[{"gurmukhi":"ਨਹੀ ਜਾਨ ਜਾਈ ਕਛੂ ਰੂਪ ਰੇਖੰ। ਕਹਾ ਬਾਸੁ ਤਾ ਕੋ ਫਿਰੈ ਕਉਨ ਭੇਖੰ।","roman":"Nahee jaan jaaee kachhoo roop rekhan | kahaa baasu taa ko phirai kaun bhekhan |","meaning_en":"","page":251},{"gurmukhi":"ਕਹਾ ਨਾਮ ਤਾ ਕੋ ਕਹਾ ਕੈ ਕਹਾਵੈ। ਕਹਾ ਮੈ ਬਖਾਨੋ ਕਹੈ ਮੈ ਨ ਆਵੈ। ੬।","roman":"Kahaa naam taa ko kahaa kai kahaavai | kahaa mai bakhaano kahai mai na aavai | 6 |","meaning_en":"","page":251}]},{"type":"verse","number":[7],"number_text":"੭।","page":252,"lines":[{"gurmukhi":"ਅਜੋਨੀ ਅਜੈ ਪਰਮ ਰੂਪੀ ਪ੍ਰਧਾਨੈ। ਅਛੇਦੀ ਅਭੇਦੀ ਅਰੂਪੀ ਮਹਾਨੈ।","roman":"Ajonee ajai param roopee pradhaanai | achhedee abhedee aroopee mahaanai |","meaning_en":"","page":252},{"gurmukhi":"ਅਸਾਧੇ ਅਗਾਧੇ ਅਗੰਜੁਲ ਗਨੀਮੇ। ਅਰੰਜੁਲ ਅਰਾਧੇ ਰਹਾਕੁਲ ਰਹੀਮੇ। ੭।","roman":"Asaadhe agaadhe aganjul ganeeme | aranjul araadhe rahaakul raheeme | 7 |","meaning_en":"","page":252}]},{"type":"verse","number":[8],"number_text":"੮।","page":252,"lines":[{"gurmukhi":"ਸਦਾ ਸਰਬਦਾ ਸਿਧਦਾ ਬੁਧਿ ਦਾਤਾ। ਨਮੋ ਲੋਕ ਲੋਕੇਸ੍ਵਰੰ ਲੋਕ ਗ੍ਯਾਤਾ।","roman":"Sadaa sarabdaa sidhdaa budhi daataa | namo lok lokesvaran lok gyaataa |","meaning_en":"","page":252},{"gurmukhi":"ਅਛੇਦੀ ਅਭੈ ਆਦਿ ਰੂਪੰ ਅਨੰਤੰ। ਅਛੇਦੀ ਅਛੈ ਆਦਿ ਅਦ੍ਵੈ ਦੁਰੰਤੰ। ੮।","roman":"Achhedee abhai aadi roopan anantan | achhedee achhai aadi advai durantan | 8 |","meaning_en":"","page":252}]},{"type":"heading","kind":"chhand","name":"ਨਰਾਜ ਛੰਦ","gurmukhi":"ਨਰਾਜ ਛੰਦ","roman":"Naraaj chhand","meaning_en":"","page":252},{"type":"verse","number":[1,9],"number_text":"੧। ੯।","page":252,"lines":[{"gurmukhi":"ਅਨੰਤ ਆਦਿ ਦੇਵ ਹੈ। ਬਿਅੰਤ ਭਰਮ ਭੇਵ ਹੈ।","roman":"Anant aadi dev hai | biant bharam bhev hai |","meaning_en":"","page":252},{"gurmukhi":"ਅਗਾਧਿ ਬਿਆਧਿ ਨਾਸ ਹੈ। ਸਦੈਵ ਸਰਬ ਪਾਸ ਹੈ। ੧। ੯।","roman":"Agaadhi biaadhi naas hai | sadaiv sarab paas hai | 1 | 9 |","meaning_en":"","page":252}]},{"type":"verse","number":[2,10],"number_text":"੨। ੧੦।","page":252,"lines":[{"gurmukhi":"ਬਚਿਤ੍ਰ ਚਿਤ੍ਰ ਚਾਪ ਹੈ। ਅਖੰਡ ਦੁਸਟ ਖਾਪ ਹੈ।","roman":"Bachitr chitr chaap hai | akhand dusat khaap hai |","meaning_en":"","page":252},{"gurmukhi":"ਅਭੇਦ ਆਦਿ ਕਾਲ ਹੈ। ਸਦੈਵ ਸਰਬ ਪਾਲ ਹੈ। ੨। ੧੦।","roman":"Abhed aadi kaal hai | sadaiv sarab paal hai | 2 | 10 |","meaning_en":"","page":252}]},{"type":"verse","number":[3,11],"number_text":"੩। ੧੧।","page":252,"lines":[{"gurmukhi":"ਅਖੰਡ ਚੰਡ ਰੂਪ ਹੈ। ਪ੍ਰਚੰਡ ਸਰਬ ਸ੍ਰੂਪ ਹੈ।","roman":"Akhand chand roop hai | prachand sarab sroop hai |","meaning_en":"","page":252},{"gurmukhi":"ਕਾਲ ਹੂੰ ਕੇ ਕਾਲ ਹੈ। ਸਦੈਵ ਰਛਪਾਲ ਹੈ। ੩। ੧੧।","roman":"Kaal hoon ke kaal hai | sadaiv rachhpaal hai | 3 | 11 |","meaning_en":"","page":252}]},{"type":"verse","number":[4,12],"number_text":"੪। ੧੨।","page":252,"lines":[{"gurmukhi":"ਕ੍ਰਿਪਾਲ ਦਿਆਲ ਰੂਪ ਹੈ। ਸਦੈਵ ਸਰਬ ਭੂਪ ਹੈ।","roman":"Kripaal diaal roop hai | sadaiv sarab bhoop hai |","meaning_en":"","page":252},{"gurmukhi":"ਅਨੰਤ ਸਰਬ ਆਸ ਹੈ। ਪਰੇਵ ਪਰਮ ਪਾਸ ਹੈ। ੪। ੧੨।","roman":"Anant sarab aas hai | parev param paas hai | 4 | 12 |","meaning_en":"","page":252}]},{"type":"verse","number":[5,13],"number_text":"੫। ੧੩।","page":252,"lines":[{"gurmukhi":"ਅਦ੍ਰਿਸਟ ਅੰਤ੍ਰ ਧਿਆਨ ਹੈ। ਸਦੈਵ ਸਰਬ ਮਾਨ ਹੈ।","roman":"Adrisat antr dhiaan hai | sadaiv sarab maan hai |","meaning_en":"","page":252},{"gurmukhi":"ਕ੍ਰਿਪਾਲ ਕਾਲ ਹੀਨ ਹੈ। ਸਦੈਵ ਸਾਧ ਅਧੀਨ ਹੈ। ੫। ੧੩।","roman":"Kripaal kaal heen hai | sadaiv saadh adheen hai | 5 | 13 |","meaning_en":"","page":252}]},{"type":"verse","number":[6,14],"number_text":"੬। ੧੪।","page":252,"lines":[{"gurmukhi":"ਭਜਸ ਤੁਯੰ। ਭਜਸ ਤੁਯੰ। ਰਹਾਉ।","roman":"Bhajas tuyan | bhajas tuyan | rahaau |","meaning_en":"","page":252},{"gurmukhi":"ਅਗਾਧਿ ਬਿਆਧਿ ਨਾਸਨੰ। ਪਰੇਯੰ ਪਰਮ ਉਪਾਸਨੰ।","roman":"Agaadhi biaadhi naasnan | pareyan param upaasnan |","meaning_en":"","page":252},{"gurmukhi":"ਤ੍ਰਿਕਾਲ ਲੋਕ ਮਾਨ ਹੈ। ਸਦੈਵ ਪੁਰਖ ਪਰਧਾਨ ਹੈ। ੬। ੧੪।","roman":"Trikaal lok maan hai | sadaiv purakh pardhaan hai | 6 | 14 |","meaning_en":"","page":252}]},{"type":"verse","number":[7,15],"number_text":"੭। ੧੫।","page":252,"lines":[{"gurmukhi":"ਤਥਸ ਤੁਯੰ। ਤਥਸ ਤੁਯੰ। ਰਹਾਉ।","roman":"Tathas tuyan | tathas tuyan | rahaau |","meaning_en":"","page":252},{"gurmukhi":"ਕ੍ਰਿਪਾਲ ਦਿਆਲ ਕਰਮ ਹੈ। ਅਗੰਜ ਭੰਜ ਭਰਮ ਹੈ।","roman":"Kripaal diaal karam hai | aganj bhanj bharam hai |","meaning_en":"","page":252},{"gurmukhi":"ਤ੍ਰਿਕਾਲ ਲੋਕ ਪਾਲ ਹੈ। ਸਦੈਵ ਸਰਬ ਦਿਆਲ ਹੈ। ੭। ੧੫।","roman":"Trikaal lok paal hai | sadaiv sarab diaal hai | 7 | 15 |","meaning_en":"","page":252}]},{"type":"verse","number":[8,16],"number_text":"੮। ੧੬।","page":252,"lines":[{"gurmukhi":"ਜਪਸ ਤੁਯੰ। ਜਪਸ ਤੁਯੰ। ਰਹਾਉ।","roman":"Japas tuyan | japas tuyan | rahaau |","meaning_en":"","page":252},{"gurmukhi":"ਮਹਾਨ ਮੋਨ ਮਾਨ ਹੈ। ਪਰੇਵ ਪਰਮ ਪ੍ਰਧਾਨ ਹੈ।","roman":"Mahaan mon maan hai | parev param pradhaan hai |","meaning_en":"","page":252},{"gurmukhi":"ਪੁਰਾਨ ਪ੍ਰੇਤ ਨਾਸਨੰ। ਸਦੈਵ ਸਰਬ ਪਾਸਨੰ। ੮। ੧੬।","roman":"Puraan pret naasnan | sadaiv sarab paasnan | 8 | 16 |","meaning_en":"","page":252}]},{"type":"verse","number":[9,17],"number_text":"੯। ੧੭।","page":252,"lines":[{"gurmukhi":"ਪ੍ਰਚੰਡ ਅਖੰਡ ਮੰਡਲੀ। ਉਦੰਡ ਰਾਜ ਸੁ ਥਲੀ।","roman":"Prachand akhand mandlee | udand raaj su thalee |","meaning_en":"","page":252},{"gurmukhi":"ਜਗੰਤ ਜੋਤਿ ਜੁਆਲਕਾ। ਜਲੰਤ ਦੀਪ ਮਾਲਕਾ। ੯। ੧੭।","roman":"Jagant joti juaalkaa | jalant deep maalkaa | 9 | 17 |","meaning_en":"","page":252}]},{"type":"verse","number":[10,18],"number_text":"੧੦। ੧੮।","page":253,"lines":[{"gurmukhi":"ਕ੍ਰਿਪਾਲ ਦਿਆਲ ਲੋਚਨੰ। ਮੰਚਕ ਬਾਣ ਮੋਚਨੰ।","roman":"Kripaal diaal lochnan | manchak baan mochnan |","meaning_en":"","page":253},{"gurmukhi":"ਸਿਰੰ ਕਰੀਟ ਧਾਰੀਯੰ। ਦਿਨੇਸ ਕ੍ਰਿਤ ਹਾਰੀਯੰ। ੧੦। ੧੮।","roman":"Siran kareet dhaareeyan | dines krit haareeyan | 10 | 18 |","meaning_en":"","page":253}]},{"type":"verse","number":[11,19],"number_text":"੧੧। ੧੯।","page":253,"lines":[{"gurmukhi":"ਬਿਸਾਲ ਲਾਲ ਲੋਚਨੰ। ਮਨੋਜ ਮਾਨ ਮੋਚਨੰ।","roman":"Bisaal laal lochnan | manoj maan mochnan |","meaning_en":"","page":253},{"gurmukhi":"ਸੁਭੰਤ ਸੀਸ ਸੁ ਪ੍ਰਭਾ। ਚਕ੍ਰਤ ਚਾਰੁ ਚੰਦ੍ਰਕਾ। ੧੧। ੧੯।","roman":"Subhant sees su prabhaa | chakrat chaaru chandrakaa | 11 | 19 |","meaning_en":"","page":253}]},{"type":"verse","number":[12,20],"number_text":"੧੨। ੨੦।","page":253,"lines":[{"gurmukhi":"ਜਗੰਤ ਜੋਤ ਜੁਆਲਕਾ। ਛਕੰਤ ਰਾਜ ਸੁ ਪ੍ਰਭਾ।","roman":"Jagant jot juaalkaa | chhakant raaj su prabhaa |","meaning_en":"","page":253},{"gurmukhi":"ਜਗੰਤ ਜੋਤਿ ਜੈਤਸੀ। ਬਦੰਤ ਕ੍ਰਿਤ ਈਸੁਰੀ। ੧੨। ੨੦।","roman":"Jagant joti jaitsee | badant krit eesuree | 12 | 20 |","meaning_en":"","page":253}]},{"type":"heading","kind":"chhand","name":"ਤ੍ਰਿਭੰਗੀ ਛੰਦ","gurmukhi":"ਤ੍ਰਿਭੰਗੀ ਛੰਦ। ਤ੍ਵਪ੍ਰਸਾਦਿ","roman":"Tribhangee chhand | tvaprasaadi","meaning_en":"","page":253,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ"},{"type":"verse","number":[1,21],"number_text":"੧। ੨੧।","page":253,"lines":[{"gurmukhi":"ਅਨਕਾਦ ਸਰੂਪੰ ਅਮਿਤ ਬਿਭੂਤੰ ਅਚਲ ਸਰੂਪੰ ਬਿਸੁ ਕਰਣੰ।","roman":"Ankaad saroopan amit bibhootan achal saroopan bisu karnan |","meaning_en":"","page":253},{"gurmukhi":"ਜਗ ਜੋਤਿ ਪ੍ਰਕਾਸੰ ਆਦਿ ਅਨਾਸੰ ਅਮਿਤ ਅਗਾਸੰ ਸਰਬ ਭਰਣੰ।","roman":"Jag joti prakaasan aadi anaasan amit agaasan sarab bharnan |","meaning_en":"","page":253},{"gurmukhi":"ਅਨਗੰਜ ਅਕਾਲੰ ਬਿਸੁ ਪ੍ਰਤਿਪਾਲੰ ਦੀਨ ਦਿਆਲੰ ਸੁਭ ਕਰਣੰ।","roman":"Anganj akaalan bisu pratipaalan deen diaalan subh karnan |","meaning_en":"","page":253},{"gurmukhi":"ਆਨੰਦ ਸਰੂਪੰ ਅਨਹਦ ਰੂਪੰ ਅਮਿਤ ਬਿਭੂਤੰ ਤਵ ਸਰਣੰ। ੧। ੨੧।","roman":"Aanand saroopan anhad roopan amit bibhootan tav sarnan | 1 | 21 |","meaning_en":"","page":253}]},{"type":"verse","number":[2,22],"number_text":"੨। ੨੨।","page":253,"lines":[{"gurmukhi":"ਬਿਸ੍ਵੰਭਰ ਭਰਣੰ ਜਗਤ ਪ੍ਰਕਰਣੰ ਅਧਰਣ ਧਰਣੰ ਸਿਸਟ ਕਰੰ।","roman":"Bisvanbhar bharnan jagat prakarnan adhran dharnan sisat karan |","meaning_en":"","page":253},{"gurmukhi":"ਆਨੰਦ ਸਰੂਪੀ ਅਨਹਦ ਰੂਪੀ ਅਮਿਤ ਬਿਭੂਤੀ ਤੇਜ ਬਰੰ।","roman":"Aanand saroopee anhad roopee amit bibhootee tej baran |","meaning_en":"","page":253},{"gurmukhi":"ਅਨਖੰਡ ਪ੍ਰਤਾਪੰ ਸਭ ਜਗ ਥਾਪੰ ਅਲਖ ਅਤਾਪੰ ਬਿਸੁ ਕਰੰ।","roman":"Ankhand prataapan sabh jag thaapan alakh ataapan bisu karan |","meaning_en":"","page":253},{"gurmukhi":"ਅਦ੍ਵੈ ਅਬਿਨਾਸੀ ਤੇਜ ਪ੍ਰਕਾਸੀ ਸਰਬ ਉਦਾਸੀ ਏਕ ਹਰੰ। ੨। ੨੨।","roman":"Advai abinaasee tej prakaasee sarab udaasee ek haran | 2 | 22 |","meaning_en":"","page":253}]},{"type":"verse","number":[3,23],"number_text":"੩। ੨੩।","page":253,"lines":[{"gurmukhi":"ਅਨਖੰਡ ਅਮੰਡੰ ਤੇਜ ਪ੍ਰਚੰਡੰ ਜੋਤਿ ਉਦੰਡੰ ਅਮਿਤ ਮਤੰ।","roman":"Ankhand amandan tej prachandan joti udandan amit matan |","meaning_en":"","page":253},{"gurmukhi":"ਅਨਭੈ ਅਨਗਾਧੰ ਅਲਖ ਅਬਾਧੰ ਬਿਸੁ ਪ੍ਰਸਾਧੰ ਅਮਿਤ ਗਤੰ।","roman":"Anbhai angaadhan alakh abaadhan bisu prasaadhan amit gatan |","meaning_en":"","page":253},{"gurmukhi":"ਆਨੰਦ ਸਰੂਪੀ ਅਨਹਦ ਰੂਪੀ ਅਚਲ ਬਿਭੂਤੀ ਭਵ ਤਰਣੰ।","roman":"Aanand saroopee anhad roopee achal bibhootee bhav tarnan |","meaning_en":"","page":253},{"gurmukhi":"ਅਨਗਾਧਿ ਅਬਾਧੰ ਜਗਤ ਪ੍ਰਸਾਧੰ ਸਰਬ ਅਰਾਧੰ ਤਵ ਸਰਣੰ। ੩। ੨੩।","roman":"Angaadhi abaadhan jagat prasaadhan sarab araadhan tav sarnan | 3 | 23 |","meaning_en":"","page":253}]},{"type":"verse","number":[4,24],"number_text":"੪। ੨੪।","page":253,"lines":[{"gurmukhi":"ਅਕਲੰਕ ਅਬਾਧੰ ਬਿਸੁ ਪ੍ਰਸਾਧੰ ਜਗਤ ਅਰਾਧੰ ਭਵ ਨਾਸੰ।","roman":"Aklank abaadhan bisu prasaadhan jagat araadhan bhav naasan |","meaning_en":"","page":253},{"gurmukhi":"ਬਿਸ੍ਵੰਭਰ ਭਰਣੰ ਕਿਲਵਿਖ ਹਰਣੰ ਪਤਤ ਉਧਰਣੰ ਸਭ ਸਾਥੰ।","roman":"Bisvanbhar bharnan kilvikh harnan patat udharnan sabh saathan |","meaning_en":"","page":253},{"gurmukhi":"ਅਨਾਥਨ ਨਾਥੇ ਅਕ੍ਰਿਤ ਅਗਾਥੇ ਅਮਿਤ ਅਨਾਥੇ ਦੁਖ ਹਰਣੰ।","roman":"Anaathan naathe akrit agaathe amit anaathe dukh harnan |","meaning_en":"","page":253},{"gurmukhi":"ਅਗੰਜ ਅਬਿਨਾਸੀ ਜੋਤਿ ਪ੍ਰਕਾਸੀ ਜਗਤ ਪ੍ਰਣਾਸੀ ਤੁਯ ਸਰਣੰ। ੪। ੨੪।","roman":"Aganj abinaasee joti prakaasee jagat pranaasee tuy sarnan | 4 | 24 |","meaning_en":"","page":253}]},{"type":"heading","kind":"chhand","name":"ਕਲਸ","gurmukhi":"ਕਲਸ","roman":"Kalas","meaning_en":"","page":254},{"type":"verse","number":[5,25],"number_text":"੫। ੨੫।","page":254,"lines":[{"gurmukhi":"ਅਮਿਤ ਤੇਜ ਜਗ ਜੋਤਿ ਪ੍ਰਕਾਸੀ। ਆਦਿ ਅਛੇਦ ਅਭੈ ਅਬਿਨਾਸੀ।","roman":"Amit tej jag joti prakaasee | aadi achhed abhai abinaasee |","meaning_en":"","page":254},{"gurmukhi":"ਪਰਮ ਤਤ ਪਰਮਾਰਥ ਪ੍ਰਕਾਸੀ। ਆਦਿ ਸਰੂਪ ਅਖੰਡ ਉਦਾਸੀ। ੫। ੨੫।","roman":"Param tat parmaarath prakaasee | aadi saroop akhand udaasee | 5 | 25 |","meaning_en":"","page":254}]},{"type":"heading","kind":"chhand","name":"ਤ੍ਰਿਭੰਗੀ ਛੰਦ","gurmukhi":"ਤ੍ਰਿਭੰਗੀ ਛੰਦ","roman":"Tribhangee chhand","meaning_en":"","page":254},{"type":"verse","number":[6,26],"number_text":"੬। ੨੬।","page":254,"lines":[{"gurmukhi":"ਅਖੰਡ ਉਦਾਸੀ ਪਰਮ ਪ੍ਰਕਾਸੀ ਆਦਿ ਅਨਾਸੀ ਬਿਸ੍ਵ ਕਰੰ।","roman":"Akhand udaasee param prakaasee aadi anaasee bisv karan |","meaning_en":"","page":254},{"gurmukhi":"ਜਗਤਾਵਲ ਕਰਤਾ ਜਗਤ ਪ੍ਰਹਰਤਾ ਸਭ ਜਗ ਭਰਤਾ ਸਿਧ ਭਰੰ।","roman":"Jagtaaval kartaa jagat prahartaa sabh jag bhartaa sidh bharan |","meaning_en":"","page":254},{"gurmukhi":"ਅਛੈ ਅਬਿਨਾਸੀ ਤੇਜ ਪ੍ਰਕਾਸੀ ਰੂਪ ਸੁ ਰਾਸੀ ਸਰਬ ਛਿਤੰ।","roman":"Achhai abinaasee tej prakaasee roop su raasee sarab chhitan |","meaning_en":"","page":254},{"gurmukhi":"ਆਨੰਦ ਸਰੂਪੀ ਅਨਹਦ ਰੂਪੀ ਅਲਖ ਬਿਭੂਤੀ ਅਮਿਤ ਗਤੰ। ੬। ੨੬।","roman":"Aanand saroopee anhad roopee alakh bibhootee amit gatan | 6 | 26 |","meaning_en":"","page":254}]},{"type":"heading","kind":"chhand","name":"ਕਲਸ","gurmukhi":"ਕਲਸ","roman":"Kalas","meaning_en":"","page":254},{"type":"verse","number":[7,27],"number_text":"੭। ੨੭।","page":254,"lines":[{"gurmukhi":"ਆਦਿ ਅਭੈ ਅਨਗਾਧਿ ਸਰੂਪੰ। ਰਾਗ ਰੰਗਿ ਜਿਹ ਰੇਖ ਨ ਰੂਪੰ।","roman":"Aadi abhai angaadhi saroopan | raag rangi jih rekh na roopan |","meaning_en":"","page":254},{"gurmukhi":"ਰੰਕ ਭਯੋ ਰਾਵਤ ਕਹੂੰ ਭੂਪੰ। ਕਹੂੰ ਸਮੁੰਦ੍ਰ ਸਰਤਾ ਕਹੂੰ ਕੂਪੰ। ੭। ੨੭।","roman":"Rank bhayo raavat kahoon bhoopan | kahoon samundr sartaa kahoon koopan | 7 | 27 |","meaning_en":"","page":254}]},{"type":"heading","kind":"chhand","name":"ਤ੍ਰਿਭੰਗੀ ਛੰਦ","gurmukhi":"ਤ੍ਰਿਭੰਗੀ ਛੰਦ","roman":"Tribhangee chhand","meaning_en":"","page":254},{"type":"verse","number":[8,28],"number_text":"੮। ੨੮।","page":254,"lines":[{"gurmukhi":"ਸਰਤਾ ਕਹੂੰ ਕੂਪੰ ਸਮੁਦ ਸਰੂਪੰ ਅਲਖ ਬਿਭੂਤੰ ਅਮਿਤ ਗਤੰ।","roman":"Sartaa kahoon koopan samud saroopan alakh bibhootan amit gatan |","meaning_en":"","page":254},{"gurmukhi":"ਅਦ੍ਵੈ ਅਬਿਨਾਸੀ ਪਰਮ ਪ੍ਰਕਾਸੀ ਤੇਜ ਸੁਰਾਸੀ ਅਕ੍ਰਿਤ ਕ੍ਰਿਤੰ।","roman":"Advai abinaasee param prakaasee tej suraasee akrit kritan |","meaning_en":"","page":254},{"gurmukhi":"ਜਿਹ ਰੂਪ ਨ ਰੇਖੰ ਅਲਖ ਅਭੇਖੰ ਅਮਿਤ ਅਦ੍ਵੈਖੰ ਸਰਬ ਮਈ।","roman":"Jih roop na rekhan alakh abhekhan amit advaikhan sarab maee |","meaning_en":"","page":254},{"gurmukhi":"ਸਭ ਕਿਲਵਿਖ ਹਰਣੰ ਪਤਿਤ ਉਧਰਣੰ ਅਸਰਣਿ ਸਰਣੰ ਏਕ ਦਈ। ੮। ੨੮।","roman":"Sabh kilvikh harnan patit udharnan asarni sarnan ek daee | 8 | 28 |","meaning_en":"","page":254}]},{"type":"heading","kind":"chhand","name":"ਕਲਸ","gurmukhi":"ਕਲਸ","roman":"Kalas","meaning_en":"","page":254},{"type":"verse","number":[9,29],"number_text":"੯। ੨੯।","page":254,"lines":[{"gurmukhi":"ਆਜਾਨੁ ਬਾਹੁ ਸਾਰੰਗ ਕਰ ਧਰਣੰ। ਅਮਿਤ ਜੋਤਿ ਜਗ ਜੋਤ ਪ੍ਰਕਰਣੰ।","roman":"Aajaanu baahu saarang kar dharnan | amit joti jag jot prakarnan |","meaning_en":"","page":254},{"gurmukhi":"ਖੜਗ ਪਾਣ ਖਲ ਦਲ ਬਲ ਹਰਣੰ। ਮਹਾਬਾਹੁ ਬਿਸ੍ਵੰਭਰ ਭਰਣੰ। ੯। ੨੯।","roman":"Kharag paan khal dal bal harnan | mahaabaahu bisvanbhar bharnan | 9 | 29 |","meaning_en":"","page":254}]},{"type":"heading","kind":"chhand","name":"ਤ੍ਰਿਭੰਗੀ ਛੰਦ","gurmukhi":"ਤ੍ਰਿਭੰਗੀ ਛੰਦ","roman":"Tribhangee chhand","meaning_en":"","page":254},{"type":"verse","number":[10,30],"number_text":"੧੦। ੩੦।","page":254,"lines":[{"gurmukhi":"ਖਲ ਦਲ ਬਲ ਹਰਣੰ ਦੁਸਟ ਬਿਦਰਣੰ ਅਸਰਣ ਸਰਣੰ ਅਮਿਤ ਗਤੰ।","roman":"Khal dal bal harnan dusat bidarnan asran sarnan amit gatan |","meaning_en":"","page":254},{"gurmukhi":"ਚੰਚਲ ਚਖ ਚਾਰਣ ਮਛ ਬਿਡਾਰਣ ਪਾਪ ਪ੍ਰਹਾਰਣ ਅਮਿਤ ਮਤੰ।","roman":"Chanchal chakh chaaran machh bidaaran paap prahaaran amit matan |","meaning_en":"","page":254},{"gurmukhi":"ਆਜਾਨ ਸੁ ਬਾਹੰ ਸਾਹਨ ਸਾਹੰ ਮਹਿਮਾ ਮਾਹੰ ਸਰਬ ਮਈ।","roman":"Aajaan su baahan saahan saahan mahimaa maahan sarab maee |","meaning_en":"","page":255},{"gurmukhi":"ਜਲ ਥਲ ਬਨ ਰਹਿਤਾ ਬਨ ਤ੍ਰਿਨਿ ਕਹਿਤਾ ਖਲ ਦਲਿ ਦਹਿਤਾ ਸੁ ਨਰਿ ਸਹੀ। ੧੦। ੩੦।","roman":"Jal thal ban rahitaa ban trini kahitaa khal dali dahitaa su nari sahee | 10 | 30 |","meaning_en":"","page":255}]},{"type":"heading","kind":"chhand","name":"ਕਲਸ","gurmukhi":"ਕਲਸ","roman":"Kalas","meaning_en":"","page":255},{"type":"verse","number":[11,31],"number_text":"੧੧। ੩੧।","page":255,"lines":[{"gurmukhi":"ਅਤਿ ਬਲਿਸਟ ਦਲ ਦੁਸਟ ਨਿਕੰਦਨ। ਅਮਿਤ ਪ੍ਰਤਾਪ ਸਗਲ ਜਗ ਬੰਦਨ।","roman":"Ati balisat dal dusat nikandan | amit prataap sagal jag bandan |","meaning_en":"","page":255},{"gurmukhi":"ਸੋਹਤ ਚਾਰੁ ਚਿਤ੍ਰ ਕਰ ਚੰਦਨ। ਪਾਪ ਪ੍ਰਹਾਰਣ ਦੁਸਟ ਦਲ ਦੰਡਨ। ੧੧। ੩੧।","roman":"Sohat chaaru chitr kar chandan | paap prahaaran dusat dal dandan | 11 | 31 |","meaning_en":"","page":255}]},{"type":"heading","kind":"chhand","name":"ਛਪੈ ਛੰਦ","gurmukhi":"ਛਪੈ ਛੰਦ","roman":"Chhapai chhand","meaning_en":"","page":255},{"type":"verse","number":[1,32],"number_text":"੧। ੩੨।","page":255,"lines":[{"gurmukhi":"ਬੇਦ ਭੇਦ ਨਹੀ ਲਖੈ ਬ੍ਰਹਮ ਬ੍ਰਹਮਾ ਨਹੀ ਬੁਝੈ।","roman":"Bed bhed nahee lakhai braham brahmaa nahee bujhai |","meaning_en":"","page":255},{"gurmukhi":"ਬਿਆਸ ਪਰਾਸੁਰ ਸੁਕ ਸਨਾਦਿ ਸਿਵ ਅੰਤੁ ਨ ਸੁਝੈ।","roman":"Biaas paraasur suk sanaadi siv antu na sujhai |","meaning_en":"","page":255},{"gurmukhi":"ਸਨਤਿ ਕੁਆਰ ਸਨਕਾਦਿ ਸਰਬ ਜਉ ਸਮਾ ਨ ਪਾਵਹਿ।","roman":"Santi kuaar sankaadi sarab jau samaa na paavhi |","meaning_en":"","page":255},{"gurmukhi":"ਲਖ ਲਖਮੀ ਲਖ ਬਿਸਨ ਕਿਸਨ ਕਈ ਨੇਤ ਬਤਾਵਹਿ।","roman":"Lakh lakhmee lakh bisan kisan kaee net bataavhi |","meaning_en":"","page":255},{"gurmukhi":"ਅਸੰਭ ਰੂਪ ਅਨਭੈ ਪ੍ਰਭਾ ਅਤਿ ਬਲਿਸਟ ਜਲਿ ਥਲਿ ਕਰਣ।","roman":"Asanbh roop anbhai prabhaa ati balisat jali thali karan |","meaning_en":"","page":255},{"gurmukhi":"ਅਚੁਤ ਅਨੰਤ ਅਦ੍ਵੈ ਅਮਿਤ ਨਾਥ ਨਿਰੰਜਨ ਤਵ ਸਰਣ। ੧। ੩੨।","roman":"Achut anant advai amit naath niranjan tav saran | 1 | 32 |","meaning_en":"","page":255}]},{"type":"verse","number":[2,33],"number_text":"੨। ੩੩।","page":255,"lines":[{"gurmukhi":"ਅਚੁਤ ਅਭੈ ਅਭੇਦ ਅਮਿਤ ਆਖੰਡ ਅਤੁਲ ਬਲ।","roman":"Achut abhai abhed amit aakhand atul bal |","meaning_en":"","page":255},{"gurmukhi":"ਅਟਲ ਅਨੰਤ ਅਨਾਦਿ ਅਖੈ ਅਖੰਡ ਪ੍ਰਬਲ ਦਲ।","roman":"Atal anant anaadi akhai akhand prabal dal |","meaning_en":"","page":255},{"gurmukhi":"ਅਮਿਤ ਅਮਿਤ ਅਨਤੋਲ ਅਭੂ ਅਨਭੇਦ ਅਭੰਜਨ।","roman":"Amit amit antol abhoo anbhed abhanjan |","meaning_en":"","page":255},{"gurmukhi":"ਅਨਬਿਕਾਰ ਆਤਮ ਸਰੂਪ ਸੁਰ ਨਰ ਮੁਨ ਰੰਜਨ।","roman":"Anbikaar aatam saroop sur nar mun ranjan |","meaning_en":"","page":255},{"gurmukhi":"ਅਬਿਕਾਰ ਰੂਪ ਅਨਭੈ ਸਦਾ ਮੁਨ ਜਨ ਗਨ ਬੰਦਤ ਚਰਨ।","roman":"Abikaar roop anbhai sadaa mun jan gan bandat charan |","meaning_en":"","page":255},{"gurmukhi":"ਭਵ ਭਰਨ ਕਰਨ ਦੁਖ ਦੋਖ ਹਰਨ ਅਤਿ ਪ੍ਰਤਾਪ ਭ੍ਰਮ ਭੈ ਹਰਨ। ੨। ੩੩।","roman":"Bhav bharan karan dukh dokh haran ati prataap bhram bhai haran | 2 | 33 |","meaning_en":"","page":255}]},{"type":"heading","kind":"chhand","name":"ਛਪੈ ਛੰਦ","gurmukhi":"ਛਪੈ ਛੰਦ। ਤ੍ਵਪ੍ਰਸਾਦਿ","roman":"Chhapai chhand | tvaprasaadi","meaning_en":"","page":255,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ"},{"type":"verse","number":[3,34],"number_text":"੩। ੩੪।","page":255,"lines":[{"gurmukhi":"ਮੁਖ ਮੰਡਲ ਪਰ ਲਸਤ ਜੋਤਿ ਉਦੋਤ ਅਮਿਤ ਗਤਿ।","roman":"Mukh mandal par lasat joti udot amit gati |","meaning_en":"","page":255},{"gurmukhi":"ਜਟਤ ਜੋਤ ਜਗਮਗਤ ਲਜਤ ਲਖ ਕੋਟਿ ਨਿਖਤਿ ਪਤਿ।","roman":"Jatat jot jagamgat lajat lakh koti nikhti pati |","meaning_en":"","page":255},{"gurmukhi":"ਚਕ੍ਰਵਰਤੀ ਚਕ੍ਰਵੈ ਚਕ੍ਰਤ ਚਉਚਕ੍ਰ ਕਰਿ ਧਰਿ।","roman":"Chakravartee chakravai chakrat chauchakr kari dhari |","meaning_en":"","page":255},{"gurmukhi":"ਪਦਮ ਨਾਥ ਪਦਮਾਛ ਨਵਲ ਨਾਰਾਇਣ ਨਰਿਹਰਿ।","roman":"Padam naath padmaachh naval naaraain narihri |","meaning_en":"","page":255},{"gurmukhi":"ਕਾਲਖ ਬਿਹੰਡਣ ਕਿਲਵਿਖ ਹਰਣ ਸੁਰ ਨਰ ਮੁਨ ਬੰਦਤ ਚਰਣ।","roman":"Kaalakh bihandan kilvikh haran sur nar mun bandat charan |","meaning_en":"","page":255},{"gurmukhi":"ਖੰਡਣ ਅਖੰਡ ਮੰਡਣ ਅਭੈ ਨਮੋ ਨਾਥ ਭਉ ਭੈ ਹਰਣ। ੩। ੩੪।","roman":"Khandan akhand mandan abhai namo naath bhau bhai haran | 3 | 34 |","meaning_en":"","page":255}]},{"type":"heading","kind":"chhand","name":"ਛਪੈ ਛੰਦ","gurmukhi":"ਛਪੈ ਛੰਦ","roman":"Chhapai chhand","meaning_en":"","page":256},{"type":"verse","number":[4,35],"number_text":"੪। ੩੫।","page":256,"lines":[{"gurmukhi":"ਨਮੋ ਨਾਥ ਨ੍ਰਿਦਾਇਕ ਨਮੋ ਨਿਮ ਰੂਪ ਨਿਰੰਜਨ।","roman":"Namo naath nridaaik namo nim roop niranjan |","meaning_en":"","page":256},{"gurmukhi":"ਅਗੰਜਾਣ ਅਗੰਜਣ ਅਭੰਜ ਅਨਭੇਦ ਅਭੰਜਨ।","roman":"Aganjaan aganjan abhanj anbhed abhanjan |","meaning_en":"","page":256},{"gurmukhi":"ਅਛੈ ਅਖੈ ਅਬਿਕਾਰ ਅਭੈ ਅਨਭਿਜ ਅਭੇਦਨ।","roman":"Achhai akhai abikaar abhai anbhij abhedan |","meaning_en":"","page":256},{"gurmukhi":"ਅਖੈਦਾਨ ਖੇਦਨ ਅਖਿਜ ਅਨਛਿਦ੍ਰ ਅਛੇਦਨ।","roman":"Akhaidaan khedan akhij anchhidr achhedan |","meaning_en":"","page":256},{"gurmukhi":"ਆਜਾਨ ਬਾਹੁ ਸਾਰੰਗਧਰ ਖੜਗ ਪਾਣ ਦੁਰਜਨ ਦਲਣ।","roman":"Aajaan baahu saarangdhar kharag paan durjan dalan |","meaning_en":"","page":256},{"gurmukhi":"ਨਰ ਵਰ ਨਰੇਸ ਨਾਇਕ ਨ੍ਰਿਪਣਿ ਨਮੋ ਨਵਲ ਜਲ ਥਲ ਰਵਣਿ। ੪। ੩੫।","roman":"Nar var nares naaik nripni namo naval jal thal ravni | 4 | 35 |","meaning_en":"","page":256}]},{"type":"verse","number":[5,36],"number_text":"੫। ੩੬।","page":256,"lines":[{"gurmukhi":"ਦੀਨ ਦਯਾਲ ਦੁਖ ਹਰਣ ਦੁਰਮਤ ਹੰਤਾ ਦੁਖ ਖੰਡਣ।","roman":"Deen dayaal dukh haran durmat hantaa dukh khandan |","meaning_en":"","page":256},{"gurmukhi":"ਮਹਾ ਮੋਨ ਮਨ ਹਰਨ ਮਦਨ ਮੂਰਤ ਮਹਿ ਮੰਡਨ।","roman":"Mahaa mon man haran madan moorat mahi mandan |","meaning_en":"","page":256},{"gurmukhi":"ਅਮਿਤ ਤੇਜ ਅਬਿਕਾਰ ਅਖੈ ਆਭੰਜ ਅਮਿਤ ਬਲ।","roman":"Amit tej abikaar akhai aabhanj amit bal |","meaning_en":"","page":256},{"gurmukhi":"ਨਿਰਭੰਜ ਨਿਰਭਉ ਨਿਰਵੈਰ ਨਿਰਜੁਰ ਨ੍ਰਿਪ ਜਲ ਥਲ।","roman":"Nirbhanj nirbhau nirvair nirjur nrip jal thal |","meaning_en":"","page":256},{"gurmukhi":"ਅਛੈ ਸਰੂਪ ਅਛੂ ਅਛਿਤ ਅਛੈ ਅਛਾਨ ਅਛਰ।","roman":"Achhai saroop achhoo achhit achhai achhaan achhar |","meaning_en":"","page":256},{"gurmukhi":"ਅਦ੍ਵੈ ਸਰੂਪ ਅਦ੍ਵਿਯ ਅਮਰ ਅਭਿਬੰਦਤ ਸੁਰ ਨਰ ਅਸੁਰ। ੫। ੩੬।","roman":"Advai saroop adviy amar abhibandat sur nar asur | 5 | 36 |","meaning_en":"","page":256}]},{"type":"verse","number":[6,37],"number_text":"੬। ੩੭।","page":256,"lines":[{"gurmukhi":"ਕੁਲ ਕਲੰਕ ਕਰਿ ਹੀਨ ਕ੍ਰਿਪਾ ਸਾਗਰ ਕਰੁਣਾ ਕਰ।","roman":"Kul kalank kari heen kripaa saagar karunaa kar |","meaning_en":"","page":256},{"gurmukhi":"ਕਰਣ ਕਾਰਣ ਸਮਰਥ ਕ੍ਰਿਪਾ ਕੀ ਸੂਰਤ ਕ੍ਰਿਤ ਧਰ।","roman":"Karan kaaran samrath kripaa kee soorat krit dhar |","meaning_en":"","page":256},{"gurmukhi":"ਕਾਲ ਕਰਮ ਕਰ ਹੀਨ ਕ੍ਰਿਆ ਜਿਹ ਕੋਇ ਨ ਬੁਝੈ।","roman":"Kaal karam kar heen kriaa jih koi na bujhai |","meaning_en":"","page":256},{"gurmukhi":"ਕਹਾ ਕਹੈ ਕਹਿ ਕਰੈ ਕਹਾ ਕਾਲਨ ਕੈ ਸੁਝੈ।","roman":"Kahaa kahai kahi karai kahaa kaalan kai sujhai |","meaning_en":"","page":256},{"gurmukhi":"ਕੰਜਲਕ ਨੈਨ ਕੰਬੂ ਗ੍ਰੀਵਹਿ ਕਟਿ ਕੇਹਰ ਕੁੰਜਰ ਗਵਨ।","roman":"Kanjlak nain kanboo greevhi kati kehar kunjar gavan |","meaning_en":"","page":256},{"gurmukhi":"ਕਦਲੀ ਕੁਰੰਕ ਕਰਪੂਰ ਗਤ ਬਿਨ ਅਕਾਲ ਦੁਜੋ ਕਵਨ। ੬। ੩੭।","roman":"Kadlee kurank karpoor gat bin akaal dujo kavan | 6 | 37 |","meaning_en":"","page":256}]},{"type":"verse","number":[7,38],"number_text":"੭। ੩੮।","page":256,"lines":[{"gurmukhi":"ਅਲਖ ਰੂਪ ਅਲੇਖ ਅਬੈ ਅਨਭੂਤ ਅਭੰਜਨ।","roman":"Alakh roop alekh abai anbhoot abhanjan |","meaning_en":"","page":256},{"gurmukhi":"ਆਦਿ ਪੁਰਖ ਅਬਿਕਾਰ ਅਜੈ ਅਨਗਾਧ ਅਗੰਜਨ।","roman":"Aadi purakh abikaar ajai angaadh aganjan |","meaning_en":"","page":256},{"gurmukhi":"ਨਿਰਬਿਕਾਰ ਨਿਰਜੁਰ ਸਰੂਪ ਨਿਰ ਦ੍ਵੈਖ ਨਿਰੰਜਨ।","roman":"Nirbikaar nirjur saroop nir dvaikh niranjan |","meaning_en":"","page":256},{"gurmukhi":"ਅਭੰਜਾਨ ਭੰਜਨ ਅਨਭੇਦ ਅਨਭੂਤ ਅਭੰਜਨ।","roman":"Abhanjaan bhanjan anbhed anbhoot abhanjan |","meaning_en":"","page":256},{"gurmukhi":"ਸਾਹਾਨ ਸਾਹ ਸੁੰਦਰ ਸੁਮਤ ਬਡ ਸਰੂਪ ਬਡਵੈ ਬਖਤ।","roman":"Saahaan saah sundar sumat bad saroop badvai bakhat |","meaning_en":"","page":256},{"gurmukhi":"ਕੋਟਕਿ ਪ੍ਰਤਾਪ ਭੂਅ ਭਾਨ ਜਿਮ ਤਪਤ ਤੇਜ ਇਸਥਿਤ ਤਖਤ। ੭। ੩੮।","roman":"Kotki prataap bhooa bhaan jim tapat tej isthit takhat | 7 | 38 |","meaning_en":"","page":256}]},{"type":"heading","kind":"chhand","name":"ਛਪੈ ਛੰਦ","gurmukhi":"ਛਪੈ ਛੰਦ। ਤ੍ਵਪ੍ਰਸਾਦਿ","roman":"Chhapai chhand | tvaprasaadi","meaning_en":"","page":257,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ"},{"type":"verse","number":[8,39],"number_text":"੮। ੩੯।","page":257,"lines":[{"gurmukhi":"ਚਕ੍ਰਤ ਚਾਰ ਚਕ੍ਰਵੈ ਚਕ੍ਰਤ ਚਉਕੁੰਟ ਚਵਗਨ।","roman":"Chakrat chaar chakravai chakrat chaukunt chavgan |","meaning_en":"","page":257},{"gurmukhi":"ਕੋਟ ਸੂਰ ਸਮ ਤੇਜ ਤੇਜ ਨਹੀ ਦੂਨ ਚਵਗਨ।","roman":"Kot soor sam tej tej nahee doon chavgan |","meaning_en":"","page":257},{"gurmukhi":"ਕੋਟ ਚੰਦ ਚਕ ਪਰੈ ਤੁਲ ਨਹੀ ਤੇਜ ਬਿਚਾਰਤ।","roman":"Kot chand chak parai tul nahee tej bichaarat |","meaning_en":"","page":257},{"gurmukhi":"ਬਿਆਸ ਪਰਾਸਰ ਬ੍ਰਹਮ ਭੇਦ ਨਹਿ ਬੇਦ ਉਚਾਰਤ।","roman":"Biaas paraasar braham bhed nahi bed uchaarat |","meaning_en":"","page":257},{"gurmukhi":"ਸਾਹਾਨ ਸਾਹ ਸਾਹਿਬ ਸੁਘਰਿ ਅਤਿ ਪ੍ਰਤਾਪ ਸੁੰਦਰ ਸਬਲ।","roman":"Saahaan saah saahib sughri ati prataap sundar sabal |","meaning_en":"","page":257},{"gurmukhi":"ਰਾਜਾਨ ਰਾਜ ਸਾਹਿਬ ਸਬਲ ਅਮਿਤ ਤੇਜ ਅਛੈ ਅਛਲ। ੮। ੩੯।","roman":"Raajaan raaj saahib sabal amit tej achhai achhal | 8 | 39 |","meaning_en":"","page":257}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ। ਤ੍ਵਪ੍ਰਸਾਦਿ","roman":"Kabitu | tvaprasaadi","meaning_en":"","page":257,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ"},{"type":"verse","number":[1,40],"number_text":"੧। ੪੦।","page":257,"lines":[{"gurmukhi":"ਗਹਿਓ ਜੋਨ ਜਾਇ ਸੋ ਅਗਾਹ ਕੈ ਕੈ ਗਾਈਅਤੁ","roman":"Gahio jon jaai so agaah kai kai gaaeeatu","meaning_en":"","page":257},{"gurmukhi":"ਛੇਦਿਓ ਜੋ ਨ ਜਾਇ ਸੋ ਅਛੇਦ ਕੈ ਪਛਾਨੀਐ।","roman":"Chhedio jo na jaai so achhed kai pachhaaneeai |","meaning_en":"","page":257},{"gurmukhi":"ਗੰਜਿਓ ਜੋ ਨ ਜਾਇ ਸੋ ਅਗੰਜ ਕੈ ਕੈ ਜਾਨੀਅਤੁ","roman":"Ganjio jo na jaai so aganj kai kai jaaneeatu","meaning_en":"","page":257},{"gurmukhi":"ਭੰਜਿਓ ਜੋ ਨ ਜਾਇ ਸੋ ਅਭੰਜ ਕੈ ਕੈ ਮਾਨੀਐ।","roman":"Bhanjio jo na jaai so abhanj kai kai maaneeai |","meaning_en":"","page":257},{"gurmukhi":"ਸਾਧਿਓ ਜੋ ਨ ਜਾਇ ਸੋ ਅਸਾਧਿ ਕੈ ਕੈ ਸਾਧ ਕਰ","roman":"Saadhio jo na jaai so asaadhi kai kai saadh kar","meaning_en":"","page":257},{"gurmukhi":"ਛਲਿਓ ਜੋ ਨ ਜਾਇ ਸੋ ਅਛਲ ਕੈ ਪ੍ਰਮਾਨੀਐ।","roman":"Chhalio jo na jaai so achhal kai pramaaneeai |","meaning_en":"","page":257},{"gurmukhi":"ਮੰਤ੍ਰ ਮੈ ਨ ਆਵੈ ਸੋ ਅਮੰਤ੍ਰ ਕੈ ਕੈ ਮਾਨੁ ਮਨ","roman":"Mantr mai na aavai so amantr kai kai maanu man","meaning_en":"","page":257},{"gurmukhi":"ਜੰਤ੍ਰ ਮੈ ਨ ਆਵੈ ਸੋ ਅਜੰਤ੍ਰ ਕੈ ਕੈ ਜਾਨੀਐ। ੧। ੪੦।","roman":"Jantr mai na aavai so ajantr kai kai jaaneeai | 1 | 40 |","meaning_en":"","page":257}]},{"type":"verse","number":[2,41],"number_text":"੨। ੪੧।","page":257,"lines":[{"gurmukhi":"ਜਾਤ ਮੈ ਨ ਆਵੈ ਸੋ ਅਜਾਤ ਕੈ ਕੈ ਜਾਨ ਜੀਅ","roman":"Jaat mai na aavai so ajaat kai kai jaan jeea","meaning_en":"","page":257},{"gurmukhi":"ਪਾਤ ਮੈ ਨ ਆਵੈ ਸੋ ਅਪਾਤ ਕੈ ਬੁਲਾਈਐ।","roman":"Paat mai na aavai so apaat kai bulaaeeai |","meaning_en":"","page":257},{"gurmukhi":"ਭੇਦ ਮੈ ਨ ਆਵੈ ਸੋ ਅਭੇਦ ਕੈ ਕੈ ਭਾਖੀਅਤੁ","roman":"Bhed mai na aavai so abhed kai kai bhaakheeatu","meaning_en":"","page":257},{"gurmukhi":"ਛੇਦ੍ਯੋ ਜੋ ਨ ਜਾਇ ਸੋ ਅਛੇਦ ਕੈ ਸੁਨਾਈਐ।","roman":"Chhedyo jo na jaai so achhed kai sunaaeeai |","meaning_en":"","page":257},{"gurmukhi":"ਖੰਡਿਓ ਜੋ ਨ ਜਾਇ ਸੋ ਅਖੰਡ ਜੂ ਕੋ ਖਿਆਲੁ ਕੀਜੈ","roman":"Khandio jo na jaai so akhand joo ko khiaalu keejai","meaning_en":"","page":257},{"gurmukhi":"ਖਿਆਲ ਮੈ ਨ ਆਵੈ ਗਮੁ ਤਾਕੋ ਸਦਾ ਖਾਈਐ।","roman":"Khiaal mai na aavai gamu taako sadaa khaaeeai |","meaning_en":"","page":257},{"gurmukhi":"ਜੰਤ੍ਰ ਮੈ ਨ ਆਵੈ ਅਜੰਤ੍ਰ ਕੈ ਕੈ ਜਾਪੀਅਤੁ","roman":"Jantr mai na aavai ajantr kai kai jaapeeatu","meaning_en":"","page":257},{"gurmukhi":"ਧਿਆਨ ਮੈ ਨ ਆਵੈ ਤਾਕੋ ਧਿਆਨੁ ਕੀਜੈ ਧਿਆਈਐ। ੨। ੪੧।","roman":"Dhiaan mai na aavai taako dhiaanu keejai dhiaaeeai | 2 | 41 |","meaning_en":"","page":257}]},{"type":"verse","number":[3,42],"number_text":"੩। ੪੨।","page":257,"lines":[{"gurmukhi":"ਛਤ੍ਰਧਾਰੀ ਛਤ੍ਰੀਪਤਿ ਛੈਲ ਰੂਪ ਛਿਤਨਾਥ","roman":"Chhatradhaaree chhatreepti chhail roop chhitnaath","meaning_en":"","page":257},{"gurmukhi":"ਛੌਣੀ ਕਰ ਛਾਇਆ ਬਰ ਛਤ੍ਰੀਪਤ ਗਾਈਐ।","roman":"Chhaunee kar chhaaiaa bar chhatreepat gaaeeai |","meaning_en":"","page":257},{"gurmukhi":"ਬਿਸ੍ਵ ਨਾਥ ਬਿਸ੍ਵੰਭਰ ਬੇਦਨਾਥ ਬਾਲਾਕਰ","roman":"Bisv naath bisvanbhar bednaath baalaakar","meaning_en":"","page":257},{"gurmukhi":"ਬਾਜੀਗਰਿ ਬਾਨ ਧਾਰੀ ਬੰਧ ਨ ਬਤਾਈਐ।","roman":"Baajeegri baan dhaaree bandh na bataaeeai |","meaning_en":"","page":257},{"gurmukhi":"ਨਿਉਲੀ ਕਰਮ ਦੂਧਾਧਾਰੀ ਬਿਦਿਆਧਰ ਬ੍ਰਹਮਚਾਰੀ","roman":"Niulee karam doodhaadhaaree bidiaadhar brahamchaaree","meaning_en":"","page":257},{"gurmukhi":"ਧਿਆਨ ਕੋ ਲਗਾਵੈ ਨੈਕ ਧਿਆਨ ਹੂੰ ਨ ਪਾਈਐ।","roman":"Dhiaan ko lagaavai naik dhiaan hoon na paaeeai |","meaning_en":"","page":257},{"gurmukhi":"ਰਾਜਨ ਕੇ ਰਾਜਾ ਮਹਾਰਾਜਨ ਕੇ ਮਹਾਰਾਜ","roman":"Raajan ke raajaa mahaaraajan ke mahaaraaj","meaning_en":"","page":257},{"gurmukhi":"ਐਸੋ ਰਾਜ ਛੋਡਿ ਅਉਰ ਦੂਜਾ ਕਉਨ ਧਿਆਈਐ। ੩। ੪੨।","roman":"Aiso raaj chhodi aur doojaa kaun dhiaaeeai | 3 | 42 |","meaning_en":"","page":257}]},{"type":"verse","number":[4,43],"number_text":"੪।੪੩।","page":258,"lines":[{"gurmukhi":"ਜੁਧ ਕੇ ਜਿਤਈਆ ਰੰਗ ਭੂਮ ਕੇ ਭਵਈਆ","roman":"Judh ke jitaeeaa rang bhoom ke bhavaeeaa","meaning_en":"","page":258},{"gurmukhi":"ਭਾਰਭੂਮ ਕੇ ਮਿਟਈਆ ਨਾਥ ਤੀਨ ਲੋਕ ਗਾਈਐ।","roman":"Bhaarbhoom ke mitaeeaa naath teen lok gaaeeai |","meaning_en":"","page":258},{"gurmukhi":"ਕਾਹੂ ਕੇ ਤਨਈਆ ਹੈ ਨ ਮਈਆ ਜਾਕੇ ਭਈਆ ਕੋਊ","roman":"Kaahoo ke tanaeeaa hai na maeeaa jaake bhaeeaa ko'oo","meaning_en":"","page":258},{"gurmukhi":"ਛਉਨੀ ਹੂ ਕੇ ਛਈਆ ਛੋਡ ਕਾ ਸਿਉ ਪ੍ਰੀਤ ਲਾਈਐ।","roman":"Chhaunee hoo ke chhaeeaa chhod kaa siu preet laaeeai |","meaning_en":"","page":258},{"gurmukhi":"ਸਾਧਨਾ ਸਧਈਆ ਧੂਲ ਧਾਨੀ ਕੇ ਧੁਜਈਆ","roman":"Saadhnaa sadhaeeaa dhool dhaanee ke dhujaeeaa","meaning_en":"","page":258},{"gurmukhi":"ਧੋਮਧਾਰ ਕੇ ਧਰਈਆ ਧਿਆਨ ਤਾਕੋ ਸਦਾ ਲਾਈਐ।","roman":"Dhomdhaar ke dharaeeaa dhiaan taako sadaa laaeeai |","meaning_en":"","page":258},{"gurmukhi":"ਆਉ ਕੇ ਬਢਈਆ ਏਕ ਨਾਮ ਕੇ ਜਪਈਆ","roman":"Aau ke badhaeeaa ek naam ke japaeeaa","meaning_en":"","page":258},{"gurmukhi":"ਅਉਰ ਕਾਮ ਕੇ ਕਰਈਆ ਛੋਡ ਅਉਰ ਕਉਨ ਧਿਆਈਐ। ੪।੪੩।","roman":"Aur kaam ke karaeeaa chhod aur kaun dhiaaeeai | 4 | 43 |","meaning_en":"","page":258}]},{"type":"verse","number":[5,44],"number_text":"੫।੪੪।","page":258,"lines":[{"gurmukhi":"ਕਾਮ ਕੋ ਕੁਨਿੰਦਾ ਖੈਰ ਖੂਬੀ ਕੋ ਦਿਹੰਦਾ","roman":"Kaam ko kunindaa khair khoobee ko dihandaa","meaning_en":"","page":258},{"gurmukhi":"ਗਜ ਗਾਜੀ ਕੋ ਗਜਿੰਦਾ ਸੋ ਕੁਨਿੰਦਾ ਕੈ ਬਤਾਈਐ।","roman":"Gaj gaajee ko gajindaa so kunindaa kai bataaeeai |","meaning_en":"","page":258},{"gurmukhi":"ਚਾਮ ਕੇ ਚਲਿੰਦਾ ਘਾਉ ਘਾਮ ਤੇ ਬਚਿੰਦਾ","roman":"Chaam ke chalindaa ghaau ghaam te bachindaa","meaning_en":"","page":258},{"gurmukhi":"ਛਤ੍ਰ ਛੈਨੀ ਕੇ ਛਲਿੰਦਾ ਸੋ ਦਿਹੰਦਾ ਕੈ ਮਨਾਈਐ।","roman":"Chhatr chhainee ke chhalindaa so dihandaa kai manaaeeai |","meaning_en":"","page":258},{"gurmukhi":"ਜਰ ਕੇ ਦਿਹੰਦਾ ਜਾਨ ਮਾਨ ਕੋ ਜਨਿੰਦਾ","roman":"Jar ke dihandaa jaan maan ko janindaa","meaning_en":"","page":258},{"gurmukhi":"ਜੋਤ ਜੇਬ ਕੋ ਗਜਿੰਦਾ ਜਾਨ ਮਾਨ ਜਾਨ ਗਾਈਐ।","roman":"Jot jeb ko gajindaa jaan maan jaan gaaeeai |","meaning_en":"","page":258},{"gurmukhi":"ਦੋਖ ਕੇ ਦਲਿੰਦਾ ਦੀਨ ਦਾਨਸ ਦਿਹੰਦਾ","roman":"Dokh ke dalindaa deen daanas dihandaa","meaning_en":"","page":258},{"gurmukhi":"ਦੋਖ ਦੁਰਜਨ ਦਲਿੰਦਾ ਧਿਆਇ ਦੂਜੋ ਕਉਨ ਧਿਆਈਐ। ੫।੪੪।","roman":"Dokh durjan dalindaa dhiaai doojo kaun dhiaaeeai | 5 | 44 |","meaning_en":"","page":258}]},{"type":"verse","number":[6,45],"number_text":"੬। ੪੫।","page":258,"lines":[{"gurmukhi":"ਸਾਲਿਸ ਸਹਿੰਦਾ ਸਿਧਤਾਈ ਕੋ ਸਧਿੰਦਾ","roman":"Saalis sahindaa sidhtaaee ko sadhindaa","meaning_en":"","page":258},{"gurmukhi":"ਅੰਗ ਅੰਗ ਮੈ ਅਵਿੰਦਾ ਏਕੁ ਏਕੋ ਨਾਥ ਜਾਨੀਐ।","roman":"Ang ang mai avindaa eku eko naath jaaneeai |","meaning_en":"","page":258},{"gurmukhi":"ਕਾਲਖ ਕਟਿੰਦਾ ਖੁਰਾਸਾਨ ਕੋ ਖੁਨਿੰਦਾ","roman":"Kaalakh katindaa khuraasaan ko khunindaa","meaning_en":"","page":258},{"gurmukhi":"ਗ੍ਰਬ ਗਾਫਲ ਗਿਲਿੰਦਾ ਗੋਲ ਗੰਜਖ ਬਖਾਨੀਐ।","roman":"Grab gaaphal gilindaa gol ganjakh bakhaaneeai |","meaning_en":"","page":258},{"gurmukhi":"ਗਾਲਬ ਗਰੰਦਾ ਜੀਤ ਤੇਜ ਕੇ ਦਿਹੰਦਾ","roman":"Gaalab garandaa jeet tej ke dihandaa","meaning_en":"","page":258},{"gurmukhi":"ਚਿਤ੍ਰ ਚਾਪ ਕੇ ਚਲਿੰਦਾ ਛੋਡ ਅਉਰ ਕਉਨ ਆਨੀਐ।","roman":"Chitr chaap ke chalindaa chhod aur kaun aaneeai |","meaning_en":"","page":258},{"gurmukhi":"ਸਤਤਾ ਦਿਹੰਦਾ ਸਤਤਾਈ ਕੋ ਸੁਖਿੰਦਾ","roman":"Sattaa dihandaa sattaaee ko sukhindaa","meaning_en":"","page":258},{"gurmukhi":"ਕਰਮ ਕਾਮ ਕੋ ਕੁਨਿੰਦਾ ਛੋਡ ਦੂਜਾ ਕਉਨ ਮਾਨੀਐ। ੬। ੪੫।","roman":"Karam kaam ko kunindaa chhod doojaa kaun maaneeai | 6 | 45 |","meaning_en":"","page":258}]},{"type":"verse","number":[7,46],"number_text":"੭। ੪੬।","page":258,"lines":[{"gurmukhi":"ਜੋਤ ਕੋ ਜਗਿੰਦਾ ਜੰਗੇ ਜਾਫਰੀ ਦਿਹੰਦਾ","roman":"Jot ko jagindaa jange jaaphree dihandaa","meaning_en":"","page":258},{"gurmukhi":"ਮਿਤ੍ਰ ਮਾਰੀ ਕੇ ਮਲਿੰਦਾ ਪੈ ਕੁਨਿੰਦਾ ਕੈ ਬਖਾਨੀਐ।","roman":"Mitr maaree ke malindaa pai kunindaa kai bakhaaneeai |","meaning_en":"","page":258},{"gurmukhi":"ਪਾਲਕ ਪੁਨਿੰਦਾ ਪਰਮ ਪਾਰਸੀ ਪ੍ਰਗਿੰਦਾ","roman":"Paalak punindaa param paarsee pragindaa","meaning_en":"","page":258},{"gurmukhi":"ਰੰਗ ਰਾਗ ਕੇ ਸੁਨਿੰਦਾ ਪੈ ਅਨੰਦਾ ਤੇਜ ਮਾਨੀਐ।","roman":"Rang raag ke sunindaa pai anandaa tej maaneeai |","meaning_en":"","page":258},{"gurmukhi":"ਜਾਪ ਕੇ ਜਪਿੰਦਾ ਖੈਰ ਖੂਬੀ ਕੇ ਦਹਿੰਦਾ","roman":"Jaap ke japindaa khair khoobee ke dahindaa","meaning_en":"","page":258},{"gurmukhi":"ਖੂਨ ਮਾਫ ਕੋ ਕੁਨਿੰਦਾ ਹੈ ਅਭਿਜ ਰੂਪ ਠਾਨੀਐ।","roman":"Khoon maaph ko kunindaa hai abhij roop thaaneeai |","meaning_en":"","page":258},{"gurmukhi":"ਆਰਜਾ ਦਹਿੰਦਾ ਰੰਗ ਰਾਗ ਕੋ ਬਿਢੰਦਾ","roman":"Aarjaa dahindaa rang raag ko bidhandaa","meaning_en":"","page":258},{"gurmukhi":"ਦੁਸਟ ਦ੍ਰੋਹ ਕੇ ਦਲਿੰਦਾ ਛੋਡ ਦੂਜੋ ਕੌਨ ਮਾਨੀਐ। ੭। ੪੬।","roman":"Dusat droh ke dalindaa chhod doojo kaun maaneeai | 7 | 46 |","meaning_en":"","page":258,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}]}]},{"type":"verse","number":[8,47],"number_text":"੮। ੪੭।","page":259,"lines":[{"gurmukhi":"ਆਤਮਾ ਪ੍ਰਧਾਨ ਜਾਹ ਸਿਧਤਾ ਸਰੂਪ ਤਾਹ","roman":"Aatmaa pradhaan jaah sidhtaa saroop taah","meaning_en":"","page":259},{"gurmukhi":"ਬੁਧਤਾ ਬਿਭੂਤ ਜਾਹ ਸਿਧਤਾ ਸੁਭਾਉ ਹੈ।","roman":"Budhtaa bibhoot jaah sidhtaa subhaau hai |","meaning_en":"","page":259},{"gurmukhi":"ਰਾਗ ਭੀ ਨ ਰੰਗ ਤਾਹਿ ਰੂਪ ਭੀ ਨ ਰੇਖ ਜਾਹਿ","roman":"Raag bhee na rang taahi roop bhee na rekh jaahi","meaning_en":"","page":259},{"gurmukhi":"ਅੰਗ ਭੀ ਸੁਰੰਗ ਤਾਹ ਰੰਗ ਕੇ ਸੁਭਾਉ ਹੈ।","roman":"Ang bhee surang taah rang ke subhaau hai |","meaning_en":"","page":259},{"gurmukhi":"ਚਿਤ੍ਰ ਸੋ ਬਚਿਤ੍ਰ ਹੈ ਪਰਮਤਾ ਪਵਿਤ੍ਰ ਹੈ","roman":"Chitr so bachitr hai paramtaa pavitr hai","meaning_en":"","page":259},{"gurmukhi":"ਸੁ ਮਿਤ੍ਰ ਹੂੰ ਕੇ ਮਿਤ੍ਰ ਹੈ ਬਿਭੂਤ ਕੋ ਉਪਾਉ ਹੈ।","roman":"Su mitr hoon ke mitr hai bibhoot ko upaau hai |","meaning_en":"","page":259},{"gurmukhi":"ਦੇਵਨ ਕੇ ਦੇਵ ਹੈ ਕਿ ਸਾਹਨ ਕੇ ਸਾਹ ਹੈ","roman":"Devan ke dev hai ki saahan ke saah hai","meaning_en":"","page":259},{"gurmukhi":"ਕਿ ਰਾਜਨ ਕੋ ਰਾਜੁ ਹੈ ਕਿ ਰਾਵਨ ਕੋ ਰਾਉ ਹੈ। ੮। ੪੭।","roman":"Ki raajan ko raaju hai ki raavan ko raau hai | 8 | 47 |","meaning_en":"","page":259}]},{"type":"heading","kind":"chhand","name":"ਬਹਿਰ ਤਵੀਲ ਛੰਦ। ਪਸਚਮੀ","gurmukhi":"ਬਹਿਰ ਤਵੀਲ ਛੰਦ। ਪਸਚਮੀ। ਤ੍ਵਪ੍ਰਸਾਦਿ","roman":"Bahir taveel chhand | pasachmee | tvaprasaadi","meaning_en":"","page":259,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ"},{"type":"verse","number":[1,48],"number_text":"੧। ੪੮।","page":259,"lines":[{"gurmukhi":"ਕਿ ਅਗੰਜਸ। ਕਿ ਅਭੰਜਸ। ਕਿ ਅਰੂਪਸ। ਕਿ ਅਰੰਜਸ। ੧। ੪੮।","roman":"Ki aganjas | ki abhanjas | ki aroopas | ki aranjas | 1 | 48 |","meaning_en":"","page":259}]},{"type":"verse","number":[2,49],"number_text":"੨। ੪੯।","page":259,"lines":[{"gurmukhi":"ਕਿ ਅਛੇਦਸ। ਕਿ ਅਭੇਦਸ। ਕਿ ਅਨਾਮਸ। ਕਿ ਅਕਾਮਸ। ੨। ੪੯।","roman":"Ki achhedas | ki abhedas | ki anaamas | ki akaamas | 2 | 49 |","meaning_en":"","page":259}]},{"type":"verse","number":[3,50],"number_text":"੩। ੫੦।","page":259,"lines":[{"gurmukhi":"ਕਿ ਅਭੇਖਸ। ਕਿ ਅਲੇਖਸ। ਕਿ ਅਨਾਦਸ। ਕਿ ਅਗਾਧਸ। ੩। ੫੦।","roman":"Ki abhekhas | ki alekhas | ki anaadas | ki agaadhas | 3 | 50 |","meaning_en":"","page":259}]},{"type":"verse","number":[4,51],"number_text":"੪। ੫੧।","page":259,"lines":[{"gurmukhi":"ਕਿ ਅਰੂਪਸ। ਕਿ ਅਭੂਤਸ। ਕਿ ਅਦਾਗਸ। ਕਿ ਅਰਾਗਸ। ੪। ੫੧।","roman":"Ki aroopas | ki abhootas | ki adaagas | ki araagas | 4 | 51 |","meaning_en":"","page":259}]},{"type":"verse","number":[5,52],"number_text":"੫। ੫੨।","page":259,"lines":[{"gurmukhi":"ਕਿ ਅਭੇਦਸ। ਕਿ ਅਛੇਦਸ। ਕਿ ਅਛਾਦਸ। ਕਿ ਅਗਾਧਸ। ੫। ੫੨।","roman":"Ki abhedas | ki achhedas | ki achhaadas | ki agaadhas | 5 | 52 |","meaning_en":"","page":259}]},{"type":"verse","number":[6,53],"number_text":"੬। ੫੩।","page":259,"lines":[{"gurmukhi":"ਕਿ ਅਗੰਜਸ। ਕਿ ਅਭੰਜਸ। ਕਿ ਅਭੇਦਸ। ਕਿ ਅਛੇਦਸ। ੬। ੫੩।","roman":"Ki aganjas | ki abhanjas | ki abhedas | ki achhedas | 6 | 53 |","meaning_en":"","page":259}]},{"type":"verse","number":[7,54],"number_text":"੭। ੫੪।","page":259,"lines":[{"gurmukhi":"ਕਿ ਅਸੇਅਸ। ਕਿ ਅਧੇਅਸ। ਕਿ ਅਗੰਜਸ। ਕਿ ਇਕੰਜਸ। ੭। ੫੪।","roman":"Ki aseas | ki adheas | ki aganjas | ki ikanjas | 7 | 54 |","meaning_en":"","page":259}]},{"type":"verse","number":[8,55],"number_text":"੮। ੫੫।","page":259,"lines":[{"gurmukhi":"ਕਿ ਉਕਾਰਸ। ਕਿ ਨਿਕਾਰਸ। ਕਿ ਅਖੰਜਸ। ਕਿ ਅਭੰਜਸ। ੮। ੫੫।","roman":"Ki ukaaras | ki nikaaras | ki akhanjas | ki abhanjas | 8 | 55 |","meaning_en":"","page":259}]},{"type":"verse","number":[9,56],"number_text":"੯। ੫੬।","page":259,"lines":[{"gurmukhi":"ਕਿ ਅਘਾਤਸ। ਕਿ ਅਕਿਆਤਸ। ਕਿ ਅਚਲਸ। ਕਿ ਅਛਲਸ। ੯। ੫੬।","roman":"Ki aghaatas | ki akiaatas | ki achlas | ki achhlas | 9 | 56 |","meaning_en":"","page":259}]},{"type":"verse","number":[10,57],"number_text":"੧੦। ੫੭।","page":259,"lines":[{"gurmukhi":"ਕਿ ਅਜਾਤਸ। ਕਿ ਅਝਾਤਸ। ਕਿ ਅਛਲਸ। ਕਿ ਅਟਲਸ। ੧੦। ੫੭।","roman":"Ki ajaatas | ki ajhaatas | ki achhlas | ki atlas | 10 | 57 |","meaning_en":"","page":259}]},{"type":"verse","number":[11,58],"number_text":"੧੧। ੫੮।","page":259,"lines":[{"gurmukhi":"ਅਟਾਟਸਚ। ਅਡਾਟਸਚ। ਅਡੰਗਸਚ। ਅਣੰਗਸਚ। ੧੧। ੫੮।","roman":"Ataatsach | adaatsach | adangsach | anangsach | 11 | 58 |","meaning_en":"","page":259}]},{"type":"verse","number":[12,59],"number_text":"੧੨। ੫੯।","page":259,"lines":[{"gurmukhi":"ਅਤਾਨਸਚ। ਅਥਾਨਸਚ। ਅਦੰਗਸਚ। ਅਨੰਗਸਚ। ੧੨। ੫੯।","roman":"Ataansach | athaansach | adangsach | anangsach | 12 | 59 |","meaning_en":"","page":259}]},{"type":"verse","number":[13,60],"number_text":"੧੩। ੬੦।","page":259,"lines":[{"gurmukhi":"ਅਪਾਰਸਚ। ਅਠਾਰਸਚ। ਅਬੇਅਸਤੁ। ਅਭੇਅਸਤ। ੧੩। ੬੦।","roman":"Apaarsach | athaarsach | abeastu | abheasat | 13 | 60 |","meaning_en":"","page":259}]},{"type":"verse","number":[14,61],"number_text":"੧੪। ੬੧।","page":259,"lines":[{"gurmukhi":"ਅਮਾਨਸਚ। ਅਹਾਨਸਚ। ਅੜੰਗਸਚ। ਅਤ੍ਰੰਗਸਚ। ੧੪। ੬੧।","roman":"Amaansach | ahaansach | arangsach | atrangsach | 14 | 61 |","meaning_en":"","page":259}]},{"type":"verse","number":[15,62],"number_text":"੧੫। ੬੨।","page":259,"lines":[{"gurmukhi":"ਅਰਾਮਸਚ। ਅਲਾਮਸਚ। ਅਜੋਧਸਚ। ਅਵੋਜਸਚ। ੧੫। ੬੨।","roman":"Araamsach | alaamsach | ajodhsach | avojsach | 15 | 62 |","meaning_en":"","page":259}]},{"type":"verse","number":[16,63],"number_text":"੧੬। ੬੩।","page":259,"lines":[{"gurmukhi":"ਅਸੇਅਸਤੁ। ਅਭੇਅਸਤੁ। ਆਅੰਗਸਤੁ। ਇਅੰਗਸਤੁ। ੧੬। ੬੩।","roman":"Aseastu | abheastu | aa'angastu | iangastu | 16 | 63 |","meaning_en":"","page":259}]},{"type":"verse","number":[17,64],"number_text":"੧੭। ੬੪।","page":259,"lines":[{"gurmukhi":"ਉਕਾਰਸਤੁ। ਅਕਾਰਸਤੁ। ਅਖੰਡਸਤੁ। ਅਡੰਗਸਤੁ। ੧੭। ੬੪।","roman":"Ukaarastu | akaarastu | akhandastu | adangastu | 17 | 64 |","meaning_en":"","page":259}]},{"type":"verse","number":[18,65],"number_text":"੧੮। ੬੫।","page":259,"lines":[{"gurmukhi":"ਕਿ ਅਤਾਪਹਿ। ਕਿ ਅਥਾਪਹਿ। ਕਿ ਅੰਦਗਹਿ। ਕਿ ਅਨੰਗਹਿ। ੧੮। ੬੫।","roman":"Ki ataaphi | ki athaaphi | ki andaghi | ki ananghi | 18 | 65 |","meaning_en":"","page":259}]},{"type":"verse","number":[19,66],"number_text":"੧੯। ੬੬।","page":259,"lines":[{"gurmukhi":"ਕਿ ਅਤਾਪਹਿ। ਕਿ ਅਥਾਪਹਿ। ਕਿ ਅਨੀਲਹਿ। ਕਿ ਸੁਨੀਲਹਿ। ੧੯। ੬੬।","roman":"Ki ataaphi | ki athaaphi | ki aneelhi | ki suneelhi | 19 | 66 |","meaning_en":"","page":259}]},{"type":"heading","kind":"chhand","name":"ਅਰਧ ਨਰਾਜਛੰਦ। ਤ੍ਵਪ੍ਰਸਾਦ","gurmukhi":"ਅਰਧ ਨਰਾਜਛੰਦ। ਤ੍ਵਪ੍ਰਸਾਦ","roman":"Aradh naraajchhand | tvaprasaad","meaning_en":"","page":260},{"type":"verse","number":[1,67],"number_text":"੧। ੬੭।","page":260,"lines":[{"gurmukhi":"ਸਜਸ ਤੁਯੰ। ਧਜਸ ਤੁਯੰ। ਅਲਸ ਤੁਯੰ। ਇਕਸ ਤੁਯੰ। ੧। ੬੭।","roman":"Sajas tuyan | dhajas tuyan | alas tuyan | ikas tuyan | 1 | 67 |","meaning_en":"","page":260}]},{"type":"verse","number":[2,68],"number_text":"੨। ੬੮।","page":260,"lines":[{"gurmukhi":"ਜਲਸ ਤੁਯੰ। ਥਲਸ ਤੁਯੰ। ਪੁਰਸ ਤੁਯੰ। ਬਨਸ ਤੁਯੰ। ੨। ੬੮।","roman":"Jalas tuyan | thalas tuyan | puras tuyan | banas tuyan | 2 | 68 |","meaning_en":"","page":260}]},{"type":"verse","number":[3,69],"number_text":"੩। ੬੯।","page":260,"lines":[{"gurmukhi":"ਗੁਰਸ ਤੁਯੰ। ਗੁਫਸ ਤੁਯੰ। ਨਿਰਸ ਤੁਯੰ। ਨਿਦਸ ਤੁਯੰ। ੩। ੬੯।","roman":"Guras tuyan | guphas tuyan | niras tuyan | nidas tuyan | 3 | 69 |","meaning_en":"","page":260}]},{"type":"verse","number":[4,70],"number_text":"੪। ੭੦।","page":260,"lines":[{"gurmukhi":"ਰਵਸ ਤੁਯੰ। ਸਸਸ ਤੁਯੰ। ਰਜਸ ਤੁਯੰ। ਤਮਸ ਤੁਯੰ। ੪। ੭੦।","roman":"Ravas tuyan | sasas tuyan | rajas tuyan | tamas tuyan | 4 | 70 |","meaning_en":"","page":260}]},{"type":"verse","number":[5,71],"number_text":"੫। ੭੧।","page":260,"lines":[{"gurmukhi":"ਧਨਸ ਤੁਯੰ। ਮਨਸ ਤੁਯੰ। ਬ੍ਰਿਛਸ ਤੁਯੰ। ਬਨਸ ਤੁਯੰ। ੫। ੭੧।","roman":"Dhanas tuyan | manas tuyan | brichhas tuyan | banas tuyan | 5 | 71 |","meaning_en":"","page":260}]},{"type":"verse","number":[6,72],"number_text":"੬। ੭੨।","page":260,"lines":[{"gurmukhi":"ਮਤਸ ਤੁਯੰ। ਗਤਸ ਤੁਯੰ। ਬ੍ਰਤਸ ਤੁਯੰ। ਚਿਤਸ ਤੁਯੰ। ੬। ੭੨।","roman":"Matas tuyan | gatas tuyan | bratas tuyan | chitas tuyan | 6 | 72 |","meaning_en":"","page":260}]},{"type":"verse","number":[7,73],"number_text":"੭। ੭੩।","page":260,"lines":[{"gurmukhi":"ਪਿਤਸ ਤੁਯੰ। ਸੁਤਸ ਤੁਯੰ। ਮਤਸ ਤੁਯੰ। ਗਤਸ ਤੁਯੰ। ੭। ੭੩।","roman":"Pitas tuyan | sutas tuyan | matas tuyan | gatas tuyan | 7 | 73 |","meaning_en":"","page":260}]},{"type":"verse","number":[8,74],"number_text":"੮। ੭੪।","page":260,"lines":[{"gurmukhi":"ਨਰਸ ਤੁਯੰ। ਤ੍ਰਿਯਸ ਤੁਯੰ। ਪਿਤਸ ਤੁਯੰ। ਬ੍ਰਿਦਸ ਤੁਯੰ। ੮। ੭੪।","roman":"Naras tuyan | triyas tuyan | pitas tuyan | bridas tuyan | 8 | 74 |","meaning_en":"","page":260}]},{"type":"verse","number":[9,75],"number_text":"੯। ੭੫।","page":260,"lines":[{"gurmukhi":"ਹਰਸ ਤੁਯੰ। ਕਰਸ ਤੁਯੰ। ਛਲਸ ਤੁਯੰ। ਬਲਸ ਤੁਯੰ। ੯। ੭੫।","roman":"Haras tuyan | karas tuyan | chhalas tuyan | balas tuyan | 9 | 75 |","meaning_en":"","page":260}]},{"type":"verse","number":[10,76],"number_text":"੧੦। ੭੬।","page":260,"lines":[{"gurmukhi":"ਉਡਸ ਤੁਯੰ। ਪੁਡਸ ਤੁਯੰ। ਗਡਸ ਤੁਯੰ। ਦਧਸ ਤੁਯੰ। ੧੦। ੭੬।","roman":"Udas tuyan | pudas tuyan | gadas tuyan | dadhas tuyan | 10 | 76 |","meaning_en":"","page":260}]},{"type":"verse","number":[11,77],"number_text":"੧੧। ੭੭।","page":260,"lines":[{"gurmukhi":"ਰਵਸ ਤੁਯੰ। ਛਪਸ ਤੁਯੰ। ਗਰਬਸ ਤੁਯੰ। ਦਿਰਬਸ ਤੁਯੰ। ੧੧। ੭੭।","roman":"Ravas tuyan | chhapas tuyan | garbas tuyan | dirbas tuyan | 11 | 77 |","meaning_en":"","page":260}]},{"type":"verse","number":[12,78],"number_text":"੧੨। ੭੮।","page":260,"lines":[{"gurmukhi":"ਜੈਅਸ ਤੁਯੰ। ਖੈਅਸ ਤੁਯੰ। ਪੈਅਸ ਤੁਯੰ। ਤ੍ਰੈਅਸ ਤੁਯੰ। ੧੨। ੭੮।","roman":"Jaias tuyan | khaias tuyan | paias tuyan | traias tuyan | 12 | 78 |","meaning_en":"","page":260}]},{"type":"heading","kind":"chhand","name":"ਨਿਰਾਜ ਛੰਦ","gurmukhi":"ਨਿਰਾਜ ਛੰਦ। ਤ੍ਵਪ੍ਰਸਾਦਿ","roman":"Niraaj chhand | tvaprasaadi","meaning_en":"","page":260,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ"},{"type":"verse","number":[1,79],"number_text":"੧। ੭੯।","page":260,"lines":[{"gurmukhi":"ਚਕੰਤ ਚਾਰ ਚੰਦ੍ਰਕਾ। ਸੁਭੰਤ ਰਾਜ ਸੁ ਪ੍ਰਭਾ।","roman":"Chakant chaar chandrakaa | subhant raaj su prabhaa |","meaning_en":"","page":260},{"gurmukhi":"ਦਵੰਤ ਦੁਸਟ ਮੰਡਲੀ। ਸੁਭੰਤ ਰਾਜ ਸੁ ਥਲੀ। ੧। ੭੯।","roman":"Davant dusat mandlee | subhant raaj su thalee | 1 | 79 |","meaning_en":"","page":260}]},{"type":"verse","number":[2,80],"number_text":"੨। ੮੦।","page":260,"lines":[{"gurmukhi":"ਚਲੰਤ ਚੰਡ ਮੰਡਕਾ। ਅਖੰਡ ਖੰਡ ਦੁਪਲਾ।","roman":"Chalant chand mandkaa | akhand khand duplaa |","meaning_en":"","page":260},{"gurmukhi":"ਖਿਵੰਤ ਬਿਜੁ ਜ੍ਵਾਲਕਾ। ਅਨੰਤ ਗਦਿ ਬਿਦਸਾ। ੨। ੮੦।","roman":"Khivant biju jvaalkaa | anant gadi bidsaa | 2 | 80 |","meaning_en":"","page":260}]},{"type":"verse","number":[3,81],"number_text":"੩। ੮੧।","page":260,"lines":[{"gurmukhi":"ਲਸੰਤ ਭਾਵ ਉਜਲੰ। ਦਲੰਤ ਦੁਖ ਦੁ ਦਲੰ।","roman":"Lasant bhaav ujlan | dalant dukh du dalan |","meaning_en":"","page":260},{"gurmukhi":"ਪਵੰਗ ਪਾਤ ਸੋਹੀਯੰ। ਸਮੁੰਦ੍ਰ ਬਾਜ ਲੋਹੀਯੰ। ੩। ੮੧।","roman":"Pavang paat soheeyan | samundr baaj loheeyan | 3 | 81 |","meaning_en":"","page":260}]},{"type":"verse","number":[4,82],"number_text":"੪। ੮੨।","page":260,"lines":[{"gurmukhi":"ਨਿਨੰਦ ਗੇਦ ਬ੍ਰਿਦਯੰ। ਅਖੇਦ ਨਾਦ ਦੁਧਰੰ।","roman":"Ninand ged bridyan | akhed naad dudhran |","meaning_en":"","page":260},{"gurmukhi":"ਅਠਟ ਬਟ ਬਟਕੰ। ਅਘਟ ਅਨਟ ਸੁਖਲੰ। ੪। ੮੨।","roman":"Athat bat batkan | aghat anat sukhlan | 4 | 82 |","meaning_en":"","page":260}]},{"type":"verse","number":[5,83],"number_text":"੫। ੮੩।","page":260,"lines":[{"gurmukhi":"ਅਖੁਟ ਤੁਟ ਦ੍ਰਿਬਕੰ। ਅਜੁਟ ਛੁਟ ਸੁਛਕੰ।","roman":"Akhut tut dribkan | ajut chhut suchhkan |","meaning_en":"","page":260},{"gurmukhi":"ਅਘੁਟ ਤੁਟ ਆਸਨੰ। ਅਲੇਖ ਅਭੇਖ ਅਨਾਸਨੰ। ੫। ੮੩।","roman":"Aghut tut aasnan | alekh abhekh anaasnan | 5 | 83 |","meaning_en":"","page":260}]},{"type":"verse","number":[6,84],"number_text":"੬। ੮੪।","page":261,"lines":[{"gurmukhi":"ਸੁਭੰਤ ਦੰਤ ਪਦੁਕੰ। ਜਲੰਤ ਸਾਮ ਸੁ ਘਟੰ।","roman":"Subhant dant padukan | jalant saam su ghatan |","meaning_en":"","page":261},{"gurmukhi":"ਸੁਭੰਤ ਛੁਦ੍ਰ ਘੰਟਕਾ। ਜਲੰਤ ਭਾਰ ਕਛਟਾ। ੬। ੮੪।","roman":"Subhant chhudr ghantkaa | jalant bhaar kachhtaa | 6 | 84 |","meaning_en":"","page":261}]},{"type":"verse","number":[7,85],"number_text":"੭। ੮੫।","page":261,"lines":[{"gurmukhi":"ਸਿਰੀਸੁ ਸੀਸ ਸੁਭੀਯੰ। ਘਟਾਕ ਬਾਨ ਉਭੀਯੰ।","roman":"Sireesu sees subheeyan | ghataak baan ubheeyan |","meaning_en":"","page":261},{"gurmukhi":"ਸੁਭੰਤ ਸੀਸ ਸਿਧਰੰ। ਜਲੰਤ ਸਿਧਰੀ ਨਰੰ। ੭। ੮੫।","roman":"Subhant sees sidhran | jalant sidhree naran | 7 | 85 |","meaning_en":"","page":261}]},{"type":"verse","number":[8,86],"number_text":"੮। ੮੬।","page":261,"lines":[{"gurmukhi":"ਚਲੰਤ ਦੰਤ ਪਤਕੰ। ਭਜੰਤ ਦੇਖਿ ਦੁਦਲੰ।","roman":"Chalant dant patkan | bhajant dekhi dudlan |","meaning_en":"","page":261},{"gurmukhi":"ਤਜੰਤ ਸਸਤ੍ਰ ਅਸਤ੍ਰਕੰ। ਚਲੰਤ ਚਕ੍ਰ ਚਉਦਿਸੰ। ੮। ੮੬।","roman":"Tajant sasatr astrakan | chalant chakr chaudisan | 8 | 86 |","meaning_en":"","page":261}]},{"type":"verse","number":[9,87],"number_text":"੯। ੮੭।","page":261,"lines":[{"gurmukhi":"ਅਗੰਮ ਤੇਜ ਸੋਭੀਯੰ। ਰਿਖੀਸ ਈਸ ਲੋਭੀਯੰ।","roman":"Aganm tej sobheeyan | rikhees ees lobheeyan |","meaning_en":"","page":261},{"gurmukhi":"ਅਨੇਕ ਬਾਰ ਧਿਆਵਹੀ। ਨ ਤਤ੍ਰ ਪਾਰ ਪਾਵਹੀ। ੯। ੮੭।","roman":"Anek baar dhiaavhee | na tatr paar paavhee | 9 | 87 |","meaning_en":"","page":261}]},{"type":"verse","number":[10,88],"number_text":"੧੦। ੮੮।","page":261,"lines":[{"gurmukhi":"ਅਧੋ ਸੁ ਧੂਮ ਧੂਮਹੀ। ਅਘੂਰ ਨੇਤ੍ਰ ਘੂਮਹੀ।","roman":"Adho su dhoom dhoomhee | aghoor netr ghoomhee |","meaning_en":"","page":261},{"gurmukhi":"ਸੁ ਪੰਚ ਅਗਨ ਸਾਧੀਯੰ। ਨ ਤਾਮ ਪਾਰ ਲਾਧੀਯੰ। ੧੦। ੮੮।","roman":"Su panch agan saadheeyan | na taam paar laadheeyan | 10 | 88 |","meaning_en":"","page":261}]},{"type":"verse","number":[11,89],"number_text":"੧੧। ੮੯।","page":261,"lines":[{"gurmukhi":"ਨਿਵਲ ਆਦਿ ਕਰਮਣੰ। ਅਨੰਤ ਦਾਨ ਧਰਮਣੰ।","roman":"Nival aadi karamnan | anant daan dharamnan |","meaning_en":"","page":261},{"gurmukhi":"ਅਨੰਤ ਤੀਰਥ ਬਾਸਨੰ। ਨ ਏਕ ਨਾਮ ਕੇ ਸਮੰ। ੧੧। ੮੯।","roman":"Anant teerath baasnan | na ek naam ke saman | 11 | 89 |","meaning_en":"","page":261}]},{"type":"verse","number":[12,90],"number_text":"੧੨। ੯੦।","page":261,"lines":[{"gurmukhi":"ਅਨੰਤ ਜਗ੍ਯ ਕਰਮਣੰ। ਗਜਾਦਿ ਆਦਿ ਧਰਮਣੰ।","roman":"Anant jagy karamnan | gajaadi aadi dharamnan |","meaning_en":"","page":261},{"gurmukhi":"ਅਨੇਕ ਦੇਸ ਭਰਮਣੰ। ਨ ਏਕ ਨਾਮ ਕੇ ਸਮੰ। ੧੨। ੯੦।","roman":"Anek des bharamnan | na ek naam ke saman | 12 | 90 |","meaning_en":"","page":261}]},{"type":"verse","number":[13,91],"number_text":"੧੩। ੯੧।","page":261,"lines":[{"gurmukhi":"ਇਕੰਤ ਕੁੰਟ ਬਾਸਨੰ। ਭ੍ਰਮੰਤ ਕੋਟਕੰ ਬਨੰ।","roman":"Ikant kunt baasnan | bhramant kotkan banan |","meaning_en":"","page":261},{"gurmukhi":"ਉਚਾਟਨਾਦ ਕਰਮਣੰ। ਅਨੇਕ ਉਦਾਸ ਭਰਮਣੰ। ੧੩। ੯੧।","roman":"Uchaatnaad karamnan | anek udaas bharamnan | 13 | 91 |","meaning_en":"","page":261}]},{"type":"verse","number":[14,92],"number_text":"੧੪। ੯੨।","page":261,"lines":[{"gurmukhi":"ਅਨੇਕ ਭੇਖ ਆਸਨੰ। ਕਰੋਰ ਕੋਟਕੰ ਬ੍ਰਤੰ।","roman":"Anek bhekh aasnan | karor kotkan bratan |","meaning_en":"","page":261},{"gurmukhi":"ਦਿਸਾ ਦਿਸਾ ਭ੍ਰਮੇਸਨੰ। ਅਨੇਕ ਭੇਖ ਪੇਖਨੰ। ੧੪। ੯੨।","roman":"Disaa disaa bhramesnan | anek bhekh pekhnan | 14 | 92 |","meaning_en":"","page":261}]},{"type":"verse","number":[15,93],"number_text":"੧੫। ੯੩।","page":261,"lines":[{"gurmukhi":"ਕਰੋਰ ਕੋਟ ਦਾਨਕੰ। ਅਨੇਕ ਜਗ੍ਯ ਕ੍ਰਤਬਿਯੰ।","roman":"Karor kot daankan | anek jagy kratbiyan |","meaning_en":"","page":261},{"gurmukhi":"ਸਨ੍ਯਾਸ ਆਦਿ ਧਰਮਣੰ। ਉਦਾਸ ਨਾਮ ਕਰਮਣੰ। ੧੫। ੯੩।","roman":"Sanyaas aadi dharamnan | udaas naam karamnan | 15 | 93 |","meaning_en":"","page":261}]},{"type":"verse","number":[16,94],"number_text":"੧੬। ੯੪।","page":261,"lines":[{"gurmukhi":"ਅਨੇਕ ਪਾਠ ਪਾਠਨੰ। ਅਨੰਤ ਠਾਟ ਠਾਟਨੰ।","roman":"Anek paath paathnan | anant thaat thaatnan |","meaning_en":"","page":261},{"gurmukhi":"ਨ ਏਕ ਨਾਮ ਕੇ ਸਮੰ। ਸਮਸਤ ਸ੍ਰਿਸਟ ਕੇ ਭ੍ਰਮੰ। ੧੬। ੯੪।","roman":"Na ek naam ke saman | samsat srisat ke bhraman | 16 | 94 |","meaning_en":"","page":261}]},{"type":"verse","number":[17,95],"number_text":"੧੭। ੯੫।","page":261,"lines":[{"gurmukhi":"ਜਗਾਦਿ ਆਦਿ ਧਰਮਣੰ। ਬੈਰਾਗ ਆਦਿ ਕਰਮਣੰ।","roman":"Jagaadi aadi dharamnan | bairaag aadi karamnan |","meaning_en":"","page":261},{"gurmukhi":"ਦਯਾਦਿ ਆਦਿ ਕਾਮਣੰ। ਅਨਾਦ ਸੰਜਮੰ ਬ੍ਰਿਦੰ। ੧੭। ੯੫।","roman":"Dayaadi aadi kaamnan | anaad sanjman bridan | 17 | 95 |","meaning_en":"","page":261}]},{"type":"verse","number":[18,96],"number_text":"੧੮। ੯੬।","page":262,"lines":[{"gurmukhi":"ਅਨੇਕ ਦੇਸ ਭਰਮਣੰ। ਕਰੋਰ ਦਾਨ ਸੰਜਮੰ।","roman":"Anek des bharamnan | karor daan sanjman |","meaning_en":"","page":262},{"gurmukhi":"ਅਨੇਕ ਗੀਤ ਗਿਆਨਨੰ। ਅਨੰਤ ਗਿਆਨ ਧਿਆਨਨੰ। ੧੮। ੯੬।","roman":"Anek geet giaannan | anant giaan dhiaannan | 18 | 96 |","meaning_en":"","page":262}]},{"type":"verse","number":[19,97],"number_text":"੧੯। ੯੭।","page":262,"lines":[{"gurmukhi":"ਅਨੰਤ ਗਿਆਨ ਸੁਤਮੰ। ਅਨੇਕ ਕ੍ਰਿਤ ਸੁ ਬ੍ਰਿਤੰ।","roman":"Anant giaan sutman | anek krit su britan |","meaning_en":"","page":262},{"gurmukhi":"ਬਿਆਸ ਨਾਰਦ ਆਦਕੰ। ਸੁ ਬ੍ਰਹਮੁ ਮਰਮ ਨਹਿ ਲਹੰ। ੧੯। ੯੭।","roman":"Biaas naarad aadkan | su brahmu maram nahi lahan | 19 | 97 |","meaning_en":"","page":262}]},{"type":"verse","number":[20,98],"number_text":"੨੦। ੯੮।","page":262,"lines":[{"gurmukhi":"ਕਰੋਰ ਜੰਤ੍ਰ ਮੰਤ੍ਰਣੰ। ਅਨੰਤ ਤੰਤ੍ਰਣੰ ਬਣੰ।","roman":"Karor jantr mantranan | anant tantranan banan |","meaning_en":"","page":262},{"gurmukhi":"ਬਸੇਖ ਬ੍ਯਾਸ ਨਾਸਨੰ। ਅਨੰਤ ਨ੍ਯਾਸ ਪ੍ਰਾਸਨੰ। ੨੦। ੯੮।","roman":"Basekh byaas naasnan | anant nyaas praasnan | 20 | 98 |","meaning_en":"","page":262}]},{"type":"verse","number":[21,99],"number_text":"੨੧। ੯੯।","page":262,"lines":[{"gurmukhi":"ਜਪੰਤ ਦੇਵ ਦੈਤਨੰ। ਥਪੰਤ ਜਛ ਗੰਧ੍ਰਬੰ।","roman":"Japant dev daitnan | thapant jachh gandhraban |","meaning_en":"","page":262},{"gurmukhi":"ਬਦੰਤ ਬਿਦਣੋਧਰੰ। ਗਣੰਤ ਸੇਸ ਉਰਗਣੰ। ੨੧। ੯੯।","roman":"Badant bidnodhran | ganant ses uragnan | 21 | 99 |","meaning_en":"","page":262}]},{"type":"verse","number":[22,100],"number_text":"੨੨। ੧੦੦।","page":262,"lines":[{"gurmukhi":"ਜਪੰਤ ਪਾਰਵਾਰਯੰ। ਸਮੁੰਦ੍ਰ ਸਪਤ ਧਾਰਯੰ।","roman":"Japant paarvaaryan | samundr sapat dhaaryan |","meaning_en":"","page":262},{"gurmukhi":"ਜਣੰਤ ਚਾਰ ਚਕ੍ਰਣੰ। ਧ੍ਰਮੰਤ ਚਕ੍ਰ ਬਕ੍ਰਣੰ। ੨੨। ੧੦੦।","roman":"Janant chaar chakranan | dhramant chakr bakranan | 22 | 100 |","meaning_en":"","page":262}]},{"type":"verse","number":[23,101],"number_text":"੨੩। ੧੦੧।","page":262,"lines":[{"gurmukhi":"ਜਪੰਤ ਪੰਨਗੰ ਨਕੰ। ਬਰੰ ਨਰੰ ਬਨਸਪਤੰ।","roman":"Japant panngan nakan | baran naran bansaptan |","meaning_en":"","page":262},{"gurmukhi":"ਅਕਾਸ ਉਰਬੀਅੰ ਜਲੰ। ਜਪੰਤ ਜੀਵ ਜਲ ਥਲੰ। ੨੩। ੧੦੧।","roman":"Akaas urbeean jalan | japant jeev jal thalan | 23 | 101 |","meaning_en":"","page":262}]},{"type":"verse","number":[24,102],"number_text":"੨੪। ੧੦੨।","page":262,"lines":[{"gurmukhi":"ਸੋ ਕੋਟ ਚਕ੍ਰ ਬਕਤ੍ਰਣੰ। ਬਦੰਤ ਬੇਦ ਚਤ੍ਰਕੰ।","roman":"So kot chakr baktranan | badant bed chatrakan |","meaning_en":"","page":262},{"gurmukhi":"ਅਸੰਭ ਅਸੰਭ ਮਾਨੀਐ। ਕਰੋਰ ਬਿਸਨ ਠਾਨੀਐ। ੨੪। ੧੦੨।","roman":"Asanbh asanbh maaneeai | karor bisan thaaneeai | 24 | 102 |","meaning_en":"","page":262}]},{"type":"verse","number":[25,103],"number_text":"੨੫। ੧੦੩।","page":262,"lines":[{"gurmukhi":"ਅਨੰਤ ਸੁਰਸੁਤੀ ਸਤੀ। ਬਦੰਤ ਕ੍ਰਿਤ ਈਸੁਰੀ।","roman":"Anant sursutee satee | badant krit eesuree |","meaning_en":"","page":262},{"gurmukhi":"ਅਨੰਤ ਅਨੰਤ ਭਾਖੀਐ। ਅਨੰਤ ਅੰਤ ਲਾਖੀਐ। ੨੫। ੧੦੩।","roman":"Anant anant bhaakheeai | anant ant laakheeai | 25 | 103 |","meaning_en":"","page":262}]},{"type":"heading","kind":"chhand","name":"ਬ੍ਰਿਧ ਨਰਾਜ ਛੰਦ","gurmukhi":"ਬ੍ਰਿਧ ਨਰਾਜ ਛੰਦ","roman":"Bridh naraaj chhand","meaning_en":"","page":262},{"type":"verse","number":[1,104],"number_text":"੧। ੧੦੪।","page":262,"lines":[{"gurmukhi":"ਅਨਾਦਿ ਅਗਾਧਿ ਬਿਆਧਿ ਆਦਿ ਅਨਾਦਿ ਕੋ ਮਨਾਈਐ।","roman":"Anaadi agaadhi biaadhi aadi anaadi ko manaaeeai |","meaning_en":"","page":262},{"gurmukhi":"ਅਗੰਜ ਅਭੰਜ ਅਰੰਜ ਅਗੰਜ ਗੰਜ ਕਉ ਧਿਆਈਐ।","roman":"Aganj abhanj aranj aganj ganj kau dhiaaeeai |","meaning_en":"","page":262},{"gurmukhi":"ਅਲੇਖ ਅਭੇਖ ਅਦ੍ਵੈਖ ਅਰੇਖ ਅਸੇਖ ਕੋ ਪਛਾਨੀਐ।","roman":"Alekh abhekh advaikh arekh asekh ko pachhaaneeai |","meaning_en":"","page":262},{"gurmukhi":"ਨ ਭੂਲ ਜੰਤ੍ਰ ਤੰਤ੍ਰ ਮੰਤ੍ਰ ਭਰਮ ਭੇਖ ਠਾਨੀਐ। ੧। ੧੦੪।","roman":"Na bhool jantr tantr mantr bharam bhekh thaaneeai | 1 | 104 |","meaning_en":"","page":262}]},{"type":"verse","number":[2,105],"number_text":"੨। ੧੦੫।","page":262,"lines":[{"gurmukhi":"ਕ੍ਰਿਪਾਲ ਲਾਲ ਅਕਾਲ ਅਪਾਲ ਦਇਆਲ ਕੋ ਉਚਾਰੀਐ।","roman":"Kripaal laal akaal apaal daiaal ko uchaareeai |","meaning_en":"","page":262},{"gurmukhi":"ਅਧਰਮ ਕਰਮ ਧਰਮ ਭਰਮ ਕਰਮ ਮੈ ਬਿਚਾਰੀਐ।","roman":"Adhram karam dharam bharam karam mai bichaareeai |","meaning_en":"","page":262},{"gurmukhi":"ਅਨੰਤ ਦਾਨ ਧਿਆਨ ਗਿਆਨ ਧਿਆਨਵਾਨ ਪੇਖੀਐ।","roman":"Anant daan dhiaan giaan dhiaanvaan pekheeai |","meaning_en":"","page":262},{"gurmukhi":"ਅਧਰਮ ਕਰਮ ਕੇ ਬਿਨਾ ਸੁ ਧਰਮ ਕਰਮ ਲੇਖੀਐ। ੨। ੧੦੫।","roman":"Adhram karam ke binaa su dharam karam lekheeai | 2 | 105 |","meaning_en":"","page":262}]},{"type":"verse","number":[3,106],"number_text":"੩। ੧੦੬।","page":263,"lines":[{"gurmukhi":"ਬ੍ਰਤਾਦਿ ਦਾਨ ਸੰਜਮਾਦਿ ਤੀਰਥ ਦੇਵ ਕਰਮਣੰ।","roman":"Brataadi daan sanjmaadi teerath dev karamnan |","meaning_en":"","page":263},{"gurmukhi":"ਹੈ ਆਦਿ ਕੁੰਜਮੇਦ ਰਾਜਸੂ ਬਿਨਾ ਨ ਭਰਮਣੰ।","roman":"Hai aadi kunjmed raajsoo binaa na bharamnan |","meaning_en":"","page":263},{"gurmukhi":"ਨਿਵਲ ਆਦਿ ਕਰਮ ਭੇਖ ਅਨੇਕ ਭੇਖ ਮਾਨੀਐ।","roman":"Nival aadi karam bhekh anek bhekh maaneeai |","meaning_en":"","page":263},{"gurmukhi":"ਅਦੇਖ ਭੇਖ ਕੇ ਬਿਨਾ ਸੁ ਕਰਮ ਭਰਮ ਜਾਨੀਐ। ੩। ੧੦੬।","roman":"Adekh bhekh ke binaa su karam bharam jaaneeai | 3 | 106 |","meaning_en":"","page":263}]},{"type":"verse","number":[4,107],"number_text":"੪। ੧੦੭।","page":263,"lines":[{"gurmukhi":"ਅਜਾਤ ਪਾਤ ਅਮਾਤ ਤਾਤ ਅਜਾਤ ਸਿਧ ਹੈ ਸਦਾ।","roman":"Ajaat paat amaat taat ajaat sidh hai sadaa |","meaning_en":"","page":263},{"gurmukhi":"ਅਸਤ੍ਰ ਮਿਤ੍ਰ ਪੁਤ੍ਰ ਪਉਤ੍ਰ ਜਤ੍ਰ ਤਤ੍ਰ ਸਰਬਦਾ।","roman":"Asatr mitr putr pautr jatr tatr sarabdaa |","meaning_en":"","page":263},{"gurmukhi":"ਅਖੰਡ ਮੰਡ ਚੰਡ ਉਦੰਡ ਅਖੰਡ ਖੰਡ ਭਾਖੀਐ।","roman":"Akhand mand chand udand akhand khand bhaakheeai |","meaning_en":"","page":263},{"gurmukhi":"ਨ ਰੂਪ ਰੰਗ ਰੇਖ ਅਲੇਖ ਭੇਖ ਮੈ ਨ ਰਾਖੀਐ। ੪। ੧੦੭।","roman":"Na roop rang rekh alekh bhekh mai na raakheeai | 4 | 107 |","meaning_en":"","page":263}]},{"type":"verse","number":[5,108],"number_text":"੫। ੧੦੮।","page":263,"lines":[{"gurmukhi":"ਅਨੰਤ ਤੀਰਥ ਆਦਿ ਆਸਨਾਦਿ ਨਾਰਦ ਆਸਨੰ।","roman":"Anant teerath aadi aasnaadi naarad aasnan |","meaning_en":"","page":263},{"gurmukhi":"ਬੈਰਾਗ ਅਉ ਸੰਨਿਆਸ ਅਉ ਅਨਾਦਿ ਜੋਗ ਪ੍ਰਾਸਨੰ।","roman":"Bairaag au sanniaas au anaadi jog praasnan |","meaning_en":"","page":263},{"gurmukhi":"ਅਨਾਦਿ ਤੀਰਥ ਸੰਜਮਾਦਿ ਬਰਤ ਨੇਮ ਪੇਖੀਐ।","roman":"Anaadi teerath sanjmaadi barat nem pekheeai |","meaning_en":"","page":263},{"gurmukhi":"ਅਨਾਦਿ ਅਗਾਧਿ ਕੇ ਬਿਨਾ ਸਮਸਤ ਭਰਮ ਲੇਖੀਐ। ੫। ੧੦੮।","roman":"Anaadi agaadhi ke binaa samsat bharam lekheeai | 5 | 108 |","meaning_en":"","page":263}]},{"type":"heading","kind":"chhand","name":"ਰਸਾਵਲ ਛੰਦ","gurmukhi":"ਰਸਾਵਲ ਛੰਦ","roman":"Rasaaval chhand","meaning_en":"","page":263},{"type":"verse","number":[1,109],"number_text":"੧। ੧੦੯।","page":263,"lines":[{"gurmukhi":"ਦਇਆਦਿ ਆਦਿ ਧਰਮੰ। ਸੰਨਿਆਸ ਆਦਿ ਕਰਮੰ।","roman":"Daiaadi aadi dharman | sanniaas aadi karman |","meaning_en":"","page":263},{"gurmukhi":"ਗਜਾਦਿ ਆਦਿ ਦਾਨੰ। ਹਯਾਦਿ ਆਦਿ ਥਾਨੰ। ੧। ੧੦੯।","roman":"Gajaadi aadi daanan | hayaadi aadi thaanan | 1 | 109 |","meaning_en":"","page":263}]},{"type":"verse","number":[2,110],"number_text":"੨। ੧੧੦।","page":263,"lines":[{"gurmukhi":"ਸੁਵਰਨ ਆਦਿ ਦਾਨੰ। ਸਮੁੰਦ੍ਰ ਆਦਿ ਇਸਨਾਨੰ।","roman":"Suvran aadi daanan | samundr aadi isnaanan |","meaning_en":"","page":263},{"gurmukhi":"ਬਿਸੁਵਾਦਿ ਆਦਿ ਭਰਮੰ। ਬਿਰਕਤਾਦਿ ਆਦਿ ਕਰਮੰ। ੨। ੧੧੦।","roman":"Bisuvaadi aadi bharman | biraktaadi aadi karman | 2 | 110 |","meaning_en":"","page":263}]},{"type":"verse","number":[3,111],"number_text":"੩। ੧੧੧।","page":263,"lines":[{"gurmukhi":"ਨਿਵਲ ਆਦਿ ਕਰਣੰ। ਸੁ ਨੀਲ ਆਦਿ ਬਰਣੰ।","roman":"Nival aadi karnan | su neel aadi barnan |","meaning_en":"","page":263},{"gurmukhi":"ਅਨੀਲ ਆਦਿ ਧਿਆਨੰ। ਜਪਤ ਤਤ ਪ੍ਰਧਾਨੰ। ੩। ੧੧੧।","roman":"Aneel aadi dhiaanan | japat tat pradhaanan | 3 | 111 |","meaning_en":"","page":263}]},{"type":"verse","number":[4,112],"number_text":"੪। ੧੧੨।","page":263,"lines":[{"gurmukhi":"ਅਮਿਤਕਾਦਿ ਭਗਤੰ। ਅਵਿਕਤਾਦਿ ਬ੍ਰਕਤੰ।","roman":"Amitkaadi bhagtan | aviktaadi braktan |","meaning_en":"","page":263},{"gurmukhi":"ਪ੍ਰਛਸਤੁਵਾ ਪ੍ਰਜਾਪੰ। ਪ੍ਰਭਗਤਾ ਅਥਾਪੰ। ੪। ੧੧੨।","roman":"Prachhastuvaa prajaapan | prabhagtaa athaapan | 4 | 112 |","meaning_en":"","page":263}]},{"type":"verse","number":[5,113],"number_text":"੫। ੧੧੩।","page":263,"lines":[{"gurmukhi":"ਸੁ ਭਗਤਾਦਿ ਕਰਣੰ। ਅਜਗਤੁਆ ਪ੍ਰਹਰਣੰ।","roman":"Su bhagtaadi karnan | ajagtuaa praharnan |","meaning_en":"","page":263},{"gurmukhi":"ਬਿਰਕਤੁਆ ਪ੍ਰਕਾਸੰ। ਅਵਿਗਤੁਆ ਪ੍ਰਣਾਸੰ। ੫। ੧੧੩।","roman":"Biraktuaa prakaasan | avigtuaa pranaasan | 5 | 113 |","meaning_en":"","page":263}]},{"type":"verse","number":[6,114],"number_text":"੬। ੧੧੪।","page":263,"lines":[{"gurmukhi":"ਸਮਸਤੁਆ ਪ੍ਰਧਾਨੰ। ਧੁਜਸਤੁਆ ਧਰਾਨੰ।","roman":"Samastuaa pradhaanan | dhujastuaa dharaanan |","meaning_en":"","page":263},{"gurmukhi":"ਅਵਿਕਤੁਆ ਅਭੰਗੰ। ਇਕਸਤੁਆ ਅਨੰਗੰ। ੬। ੧੧੪।","roman":"Aviktuaa abhangan | ikastuaa anangan | 6 | 114 |","meaning_en":"","page":263}]},{"type":"verse","number":[7,115],"number_text":"੭। ੧੧੫।","page":264,"lines":[{"gurmukhi":"ਉਅਸਤੁਆ ਅਕਾਰੰ। ਕ੍ਰਿਪਸਤੁਆ ਕ੍ਰਿਪਾਰੰ।","roman":"Uastuaa akaaran | kripastuaa kripaaran |","meaning_en":"","page":264},{"gurmukhi":"ਖਿਤਸਤੁਆ ਅਖੰਡੰ। ਗਤਸਤੁਆ ਅਗੰਡੰ। ੭। ੧੧੫।","roman":"Khitastuaa akhandan | gatastuaa agandan | 7 | 115 |","meaning_en":"","page":264}]},{"type":"verse","number":[8,116],"number_text":"੮। ੧੧੬।","page":264,"lines":[{"gurmukhi":"ਘਰਸਤੁਆ ਘਰਾਨੰ। ਙ੍ਰਿਅਸਤੁਆ ਙ੍ਰਿਹਾਲੰ।","roman":"Gharastuaa gharaanan | ngriastuaa ngrihaalan |","meaning_en":"","page":264},{"gurmukhi":"ਚਿਤਸਤੁਆ ਅਤਾਪੰ। ਛਿਤਸਤੁਆ ਅਛਾਪੰ। ੮। ੧੧੬।","roman":"Chitastuaa ataapan | chhitastuaa achhaapan | 8 | 116 |","meaning_en":"","page":264}]},{"type":"verse","number":[9,117],"number_text":"੯। ੧੧੭।","page":264,"lines":[{"gurmukhi":"ਜਿਤਸਤੁਆ ਅਜਾਪੰ। ਝਿਕਸਤੁਆ ਅਝਾਪੰ।","roman":"Jitastuaa ajaapan | jhikastuaa ajhaapan |","meaning_en":"","page":264},{"gurmukhi":"ਇਕਸਤੁਆ ਅਨੇਕੰ। ਟੁਟਸਤੁਆ ਅਟੇਟੰ। ੯। ੧੧੭।","roman":"Ikastuaa anekan | tutastuaa atetan | 9 | 117 |","meaning_en":"","page":264}]},{"type":"verse","number":[10,118],"number_text":"੧੦। ੧੧੮।","page":264,"lines":[{"gurmukhi":"ਠਟਸਤੁਆ ਅਠਾਟੰ। ਡਟਸਤੁਆ ਅਡਾਟੰ।","roman":"Thatastuaa athaatan | datastuaa adaatan |","meaning_en":"","page":264},{"gurmukhi":"ਢਟਸਤੁਆ ਅਢਾਪੰ। ਣਕਸਤੁਆ ਅਣਾਪੰ। ੧੦। ੧੧੮।","roman":"Dhatastuaa adhaapan | nakastuaa anaapan | 10 | 118 |","meaning_en":"","page":264}]},{"type":"verse","number":[11,119],"number_text":"੧੧। ੧੧੯।","page":264,"lines":[{"gurmukhi":"ਤਪਸਤੁਆ ਅਤਾਪੰ। ਥਪਸਤੁਆ ਅਥਾਪੰ।","roman":"Tapastuaa ataapan | thapastuaa athaapan |","meaning_en":"","page":264},{"gurmukhi":"ਦਲਸਤੁਆਦਿ ਦੋਖੰ। ਨਹਿਸਤੁਆ ਅਨੋਖੰ। ੧੧। ੧੧੯।","roman":"Dalastuaadi dokhan | nahistuaa anokhan | 11 | 119 |","meaning_en":"","page":264}]},{"type":"verse","number":[12,120],"number_text":"੧੨। ੧੨੦।","page":264,"lines":[{"gurmukhi":"ਅਪਕਤੁਆ ਅਪਾਨੰ। ਫਲਕਤੁਆ ਫਲਾਨੰ।","roman":"Apaktuaa apaanan | phalaktuaa phalaanan |","meaning_en":"","page":264},{"gurmukhi":"ਬਦਕਤੁਆ ਬਿਸੇਖੰ। ਭਜਸਤੁਆ ਅਭੇਖੰ। ੧੨। ੧੨੦।","roman":"Badaktuaa bisekhan | bhajastuaa abhekhan | 12 | 120 |","meaning_en":"","page":264}]},{"type":"verse","number":[13,121],"number_text":"੧੩। ੧੨੧।","page":264,"lines":[{"gurmukhi":"ਮਤਸਤੁਆ ਫਲਾਨੰ। ਹਰਿਕਤੁਆ ਹਿਰਦਾਨੰ।","roman":"Matastuaa phalaanan | hariktuaa hirdaanan |","meaning_en":"","page":264},{"gurmukhi":"ਅੜਕਤੁਆ ਅੜੰਗੰ। ਤ੍ਰਿਕਸਤੁਆ ਤ੍ਰਿਭੰਗੰ। ੧੩। ੧੨੧।","roman":"Araktuaa arangan | trikastuaa tribhangan | 13 | 121 |","meaning_en":"","page":264}]},{"type":"verse","number":[14,122],"number_text":"੧੪। ੧੨੨।","page":264,"lines":[{"gurmukhi":"ਰੰਗਸਤੁਆ ਅਰੰਗੰ। ਲਵਸਤੁਆ ਅਲੰਗੰ।","roman":"Rangastuaa arangan | lavastuaa alangan |","meaning_en":"","page":264},{"gurmukhi":"ਯਕਸਤੁਆ ਯਕਾਪੰ। ਇਕਸਤੁਆ ਇਕਾਪੰ। ੧੪। ੧੨੨।","roman":"Yakastuaa yakaapan | ikastuaa ikaapan | 14 | 122 |","meaning_en":"","page":264}]},{"type":"verse","number":[15,123],"number_text":"੧੫। ੧੨੩।","page":264,"lines":[{"gurmukhi":"ਵਦਿਸਤੁਆ ਵਰਦਾਨੰ। ਯਕਸਤੁਆ ਇਕਾਨੰ।","roman":"Vadistuaa vardaanan | yakastuaa ikaanan |","meaning_en":"","page":264},{"gurmukhi":"ਲਵਸਤੁਆ ਅਲੇਖੰ। ਰਰਿਸਤੁਆ ਅਰੇਖੰ। ੧੫। ੧੨੩।","roman":"Lavastuaa alekhan | raristuaa arekhan | 15 | 123 |","meaning_en":"","page":264}]},{"type":"verse","number":[16,124],"number_text":"੧੬। ੧੨੪।","page":264,"lines":[{"gurmukhi":"ਤ੍ਰਿਅਸਤੁਆ ਤ੍ਰਿਭੰਗੇ। ਹਰਿਸਤੁਆ ਹਰੰਗੇ।","roman":"Triastuaa tribhange | haristuaa harange |","meaning_en":"","page":264},{"gurmukhi":"ਮਹਿਸਤੁਆ ਮਹੇਸੰ। ਭਜਸਤੁਆ ਅਭੇਸੰ। ੧੬। ੧੨੪।","roman":"Mahistuaa mahesan | bhajastuaa abhesan | 16 | 124 |","meaning_en":"","page":264}]},{"type":"verse","number":[17,125],"number_text":"੧੭। ੧੨੫।","page":264,"lines":[{"gurmukhi":"ਬਰਸਤੁਆ ਬਰਾਨੰ। ਪਲਸਤੁਆ ਫਲਾਨੰ।","roman":"Barastuaa baraanan | palastuaa phalaanan |","meaning_en":"","page":264},{"gurmukhi":"ਨਰਸਤੁਆ ਨਰੇਸੰ। ਦਲਸਤੁਸਾ ਦਲੇਸੰ। ੧੭। ੧੨੫।","roman":"Narastuaa naresan | dalastusaa dalesan | 17 | 125 |","meaning_en":"","page":264}]},{"type":"heading","kind":"chhand","name":"ਪਾਧੜੀ ਛੰਦ","gurmukhi":"ਪਾਧੜੀ ਛੰਦ। ਤ੍ਵਪ੍ਰਸਾਦਿ","roman":"Paadhree chhand | tvaprasaadi","meaning_en":"","page":264,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ"},{"type":"verse","number":[1,126],"number_text":"੧। ੧੨੬।","page":264,"lines":[{"gurmukhi":"ਦਿਨ ਅਜਬ ਏਕ ਆਤਮਾ ਰਾਮ। ਅਨਭਉ ਸਰੂਪ ਅਨਹਦ ਅਕਾਮ।","roman":"Din ajab ek aatmaa raam | anbhau saroop anhad akaam |","meaning_en":"","page":264},{"gurmukhi":"ਅਨਛਿਜ ਤੇਜ ਆਜਾਨ ਬਾਹੁ। ਰਾਜਾਨ ਰਾਜ ਸਾਹਾਨ ਸਾਹੁ। ੧। ੧੨੬।","roman":"Anchhij tej aajaan baahu | raajaan raaj saahaan saahu | 1 | 126 |","meaning_en":"","page":264}]},{"type":"verse","number":[2,127],"number_text":"੨। ੧੨੭।","page":265,"lines":[{"gurmukhi":"ਉਚਰਿਓ ਆਤਮਾ ਪਰਮਾਤਮਾ ਸੰਗ। ਉਤਭੁਜ ਸਰੂਪ ਅਬਿਗਤ ਅਭੰਗ।","roman":"Uchrio aatmaa parmaatmaa sang | utbhuj saroop abigat abhang |","meaning_en":"","page":265},{"gurmukhi":"ਇਹ ਕਉਨ ਆਹਿ ਆਤਮਾ ਸਰੂਪ। ਜਿਹ ਅਮਿਤ ਤੇਜਿ ਅਤਿਭੁਤਿ ਬਿਭੂਤਿ। ੨। ੧੨੭।","roman":"Ih kaun aahi aatmaa saroop | jih amit teji atibhuti bibhooti | 2 | 127 |","meaning_en":"","page":265}]},{"type":"heading","kind":"speaker","name":"ਪਰਾਤਮਾ ਬਾਚ","gurmukhi":"ਪਰਾਤਮਾ ਬਾਚ","roman":"Paraatmaa baach","meaning_en":"","page":265},{"type":"verse","number":[3,128],"number_text":"੩। ੧੨੮।","page":265,"lines":[{"gurmukhi":"ਯਹਿ ਬ੍ਰਹਮ ਆਹਿ ਆਤਮਾ ਰਾਮ। ਜਿਹ ਅਮਿਤ ਤੇਜਿ ਅਬਿਗਤ ਅਕਾਮ।","roman":"Yahi braham aahi aatmaa raam | jih amit teji abigat akaam |","meaning_en":"","page":265},{"gurmukhi":"ਜਿਹ ਭੇਦ ਭਰਮ ਨਹੀ ਕਰਮ ਕਾਲ। ਜਿਹ ਸਤ੍ਰ ਮਿਤ੍ਰ ਸਰਬਾ ਦਿਆਲ। ੩। ੧੨੮।","roman":"Jih bhed bharam nahee karam kaal | jih satr mitr sarbaa diaal | 3 | 128 |","meaning_en":"","page":265}]},{"type":"verse","number":[4,129],"number_text":"੪। ੧੨੯।","page":265,"lines":[{"gurmukhi":"ਡੋਬਿਯੋ ਨ ਡੁਬੈ ਸੋਖਿਯੋ ਨ ਜਾਇ। ਕਟਿਯੋ ਨ ਕਟੈ ਨ ਬਾਰਿਯੋ ਬਰਾਇ।","roman":"Dobiyo na dubai sokhiyo na jaai | katiyo na katai na baariyo baraai |","meaning_en":"","page":265},{"gurmukhi":"ਛਿਜੈ ਨ ਨੈਕ ਸਤ ਸਸਤ੍ਰ ਪਾਤ। ਜਿਹ ਸਤ੍ਰ ਮਿਤ੍ਰ ਨਹੀ ਜਾਤ ਪਾਤ। ੪। ੧੨੯।","roman":"Chhijai na naik sat sasatr paat | jih satr mitr nahee jaat paat | 4 | 129 |","meaning_en":"","page":265}]},{"type":"verse","number":[5,130],"number_text":"੫। ੧੩੦।","page":265,"lines":[{"gurmukhi":"ਸਤ੍ਰ ਸਹੰਸ ਸਤਿ ਸਤਿ ਪ੍ਰਘਾਇ। ਛਿਜੈ ਨ ਨੈਕ ਖੰਡਿਓ ਨ ਜਾਇ।","roman":"Satr sahans sati sati praghaai | chhijai na naik khandio na jaai |","meaning_en":"","page":265},{"gurmukhi":"ਨਹੀ ਜਰੈ ਨੈਕ ਪਾਵਕ ਮੰਝਾਰ। ਬੋਰੈ ਨ ਸਿੰਧ ਸੋਖੈ ਨ ਬ੍ਯਾਰ। ੫। ੧੩੦।","roman":"Nahee jarai naik paavak manjhaar | borai na sindh sokhai na byaar | 5 | 130 |","meaning_en":"","page":265}]},{"type":"verse","number":[6,131],"number_text":"੬। ੧੩੧।","page":265,"lines":[{"gurmukhi":"ਇਕ ਕਰ੍ਯੋ ਪ੍ਰਸਨ ਆਤਮਾ ਦੇਵ। ਅਨਭੰਗ ਰੂਪ ਅਨਿਭਉ ਅਭੇਵ।","roman":"Ik karyo prasan aatmaa dev | anbhang roop anibhau abhev |","meaning_en":"","page":265},{"gurmukhi":"ਯਹਿ ਚਤੁਰ ਵਰਗ ਸੰਸਾਰ ਦਾਨ। ਕਿਹੁ ਚਤੁਰ ਵਰਗ ਕਿਜੈ ਵਖਿਆਨ। ੬। ੧੩੧।","roman":"Yahi chatur varag sansaar daan | kihu chatur varag kijai vakhiaan | 6 | 131 |","meaning_en":"","page":265}]},{"type":"verse","number":[7,132],"number_text":"੭। ੧੩੨।","page":265,"lines":[{"gurmukhi":"ਇਕ ਰਾਜੁ ਧਰਮ ਇਕ ਦਾਨ ਧਰਮ। ਇਕ ਭੋਗ ਧਰਮ ਇਕ ਮੋਛ ਕਰਮ।","roman":"Ik raaju dharam ik daan dharam | ik bhog dharam ik mochh karam |","meaning_en":"","page":265},{"gurmukhi":"ਇਕ ਚਤੁਰ ਵਰਗ ਸਭ ਜਗ ਭਣੰਤ। ਸੇ ਆਤਮਾਹ ਪਰਾਤਮਾ ਪੁਛੰਤ। ੭। ੧੩੨।","roman":"Ik chatur varag sabh jag bhanant | se aatmaah paraatmaa puchhant | 7 | 132 |","meaning_en":"","page":265}]},{"type":"verse","number":[8,133],"number_text":"੮। ੧੩੩।","page":265,"lines":[{"gurmukhi":"ਇਕ ਰਾਜ ਧਰਮ ਇਕ ਧਰਮ ਦਾਨ। ਇਕ ਭੋਗ ਧਰਮ ਇਕ ਮੋਛਵਾਨ।","roman":"Ik raaj dharam ik dharam daan | ik bhog dharam ik mochhvaan |","meaning_en":"","page":265},{"gurmukhi":"ਤੁਮ ਕਹੋ ਚਤ੍ਰ ਚਤ੍ਰੈ ਬਿਚਾਰ। ਜੇ ਤ੍ਰਿਕਾਲ ਭਏ ਜੁਗ ਅਪਾਰ। ੮। ੧੩੩।","roman":"Tum kaho chatr chatrai bichaar | je trikaal bhae jug apaar | 8 | 133 |","meaning_en":"","page":265}]},{"type":"verse","number":[9,134],"number_text":"੯। ੧੩੪।","page":265,"lines":[{"gurmukhi":"ਬਰਨੰਨ ਕਰੋ ਤੁਮ ਪ੍ਰਿਥਮ ਦਾਨ। ਜਿਮ ਦਾਨ ਧਰਮ ਕਿੰਨੇ ਨ੍ਰਿਪਾਨ।","roman":"Barnann karo tum pritham daan | jim daan dharam kinne nripaan |","meaning_en":"","page":265},{"gurmukhi":"ਸਤਿਜੁਗ ਕਰਮ ਸੁਰ ਦਾਨ ਦੰਤ। ਭੂਮਾਦਿ ਦਾਨ ਕੀਨੇ ਅਕੰਥ। ੯। ੧੩੪।","roman":"Satijug karam sur daan dant | bhoomaadi daan keene akanth | 9 | 134 |","meaning_en":"","page":265}]},{"type":"verse","number":[10,135],"number_text":"੧੦। ੧੩੫।","page":265,"lines":[{"gurmukhi":"ਤ੍ਰੈ ਜੁਗ ਮਹੀਪ ਬਰਨੇ ਨ ਜਾਤ। ਗਾਥਾ ਅਨੰਤ ਉਪਮਾ ਅਗਾਤ।","roman":"Trai jug maheep barne na jaat | gaathaa anant upmaa agaat |","meaning_en":"","page":265},{"gurmukhi":"ਜੋ ਕੀਏ ਜਗਤ ਮੈ ਜਗ ਧਰਮ। ਬਰਨੇ ਨ ਜਾਹਿ ਤੇ ਅਮਿਤ ਕਰਮ। ੧੦। ੧੩੫।","roman":"Jo kee'e jagat mai jag dharam | barne na jaahi te amit karam | 10 | 135 |","meaning_en":"","page":265}]},{"type":"verse","number":[11,136],"number_text":"੧੧। ੧੩੬।","page":265,"lines":[{"gurmukhi":"ਕਲਜੁਗ ਤੇ ਆਦਿ ਜੋ ਭਏ ਮਹੀਪ। ਇਹਿ ਭਰਥ ਖੰਡਿ ਮਹਿ ਜੰਬੂ ਦੀਪ।","roman":"Kaljug te aadi jo bhae maheep | ihi bharath khandi mahi janboo deep |","meaning_en":"","page":265},{"gurmukhi":"ਤ੍ਵ ਬਲ ਪ੍ਰਤਾਪ ਬਰਣੌ ਸੁ ਤ੍ਰੈਣ। ਰਾਜਾ ਯੁਧਿਸਟ੍ਰ ਭੂ ਭਰਥ ਏਣ। ੧੧। ੧੩੬।","roman":"Tva bal prataap barnau su train | raajaa yudhisatr bhoo bharath en | 11 | 136 |","meaning_en":"","page":265}]},{"type":"verse","number":[12,137],"number_text":"੧੨। ੧੩੭।","page":265,"lines":[{"gurmukhi":"ਖੰਡੇ ਅਖੰਡ ਜਿਹ ਚਤੁਰ ਖੰਡ। ਕੈਰੌ ਕੁਰਖੇਤ੍ਰ ਮਾਰੇ ਪ੍ਰਚੰਡ।","roman":"Khande akhand jih chatur khand | kairau kurkhetr maare prachand |","meaning_en":"","page":265},{"gurmukhi":"ਜਿਹ ਚਤੁਰ ਕੁੰਡ ਜਿਤਿਯੋ ਦੁਬਾਰ। ਅਰਜਨ ਭੀਮਾਦਿ ਭ੍ਰਾਤਾ ਜੁਝਾਰ। ੧੨। ੧੩੭।","roman":"Jih chatur kund jitiyo dubaar | arjan bheemaadi bhraataa jujhaar | 12 | 137 |","meaning_en":"","page":266}]},{"type":"verse","number":[13,138],"number_text":"੧੩। ੧੩੮।","page":266,"lines":[{"gurmukhi":"ਅਰਜਨ ਪਠਿਯੋ ਉਤਰ ਦਿਸਾਨ। ਭੀਮਹਿ ਕਰਾਇ ਪੂਰਬ ਪਯਾਨ।","roman":"Arjan pathiyo utar disaan | bheemhi karaai poorab payaan |","meaning_en":"","page":266},{"gurmukhi":"ਸਹਿਦੇਵ ਪਠਿਯੋ ਦਛਣ ਸੁਦੇਸ। ਨੁਕਲਹਿ ਪਠਾਇ ਪਛਮ ਪ੍ਰਵੇਸ। ੧੩। ੧੩੮।","roman":"Sahidev pathiyo dachhan sudes | nukalhi pathaai pachham praves | 13 | 138 |","meaning_en":"","page":266}]},{"type":"verse","number":[14,139],"number_text":"੧੪। ੧੩੯।","page":266,"lines":[{"gurmukhi":"ਮੰਡੇ ਮਹੀਪ ਖੰਡਿਯੋ ਖਤ੍ਰਾਣ। ਜਿਤੇ ਅਜੀਤ ਮੰਡੇ ਮਹਾਨ।","roman":"Mande maheep khandiyo khatraan | jite ajeet mande mahaan |","meaning_en":"","page":266},{"gurmukhi":"ਖੰਡਿਯੋ ਸੁ ਉਤ੍ਰ ਖੁਰਾਸਾਨ ਦੇਸ। ਦਛਨ ਪੂਰਬ ਜੀਤੇ ਨਰੇਸ। ੧੪। ੧੩੯।","roman":"Khandiyo su utr khuraasaan des | dachhan poorab jeete nares | 14 | 139 |","meaning_en":"","page":266}]},{"type":"verse","number":[15,140],"number_text":"੧੫। ੧੪੦।","page":266,"lines":[{"gurmukhi":"ਖਗ ਖੰਡ ਖੰਡ ਜੀਤੇ ਮਹੀਪ। ਬਜਿਯੋ ਨਿਸਾਨ ਇਹ ਜੰਬੂਦੀਪ।","roman":"Khag khand khand jeete maheep | bajiyo nisaan ih janboodeep |","meaning_en":"","page":266},{"gurmukhi":"ਇਕ ਠਉਰ ਕੀਏ ਸਬ ਦੇਸ ਰਾਉ। ਮਖ ਰਾਜਸੂਅ ਕੋ ਕੀਓ ਚਾਉ। ੧੫। ੧੪੦।","roman":"Ik thaur kee'e sab des raau | makh raajsooa ko keeo chaau | 15 | 140 |","meaning_en":"","page":266}]},{"type":"verse","number":[16,141],"number_text":"੧੬।੧੪੧।","page":266,"lines":[{"gurmukhi":"ਸਬ ਦੇਸ ਦੇਸ ਪਠੇ ਸੁ ਪਤ੍ਰ। ਜਿਤ ਜਿਤ ਗੁਨਾਢ ਕੀਏ ਇਕਤ੍ਰ।","roman":"Sab des des pathe su patr | jit jit gunaadh kee'e ikatr |","meaning_en":"","page":266},{"gurmukhi":"ਮਖ ਰਾਜਸੂਅ ਕੋ ਕੀਯੋ ਅਰੰਭ। ਨ੍ਰਿਪ ਬਹੁਤ ਬੁਲਾਇ ਜਿਤੇ ਅਸੰਭ। ੧੬।੧੪੧।","roman":"Makh raajsooa ko keeyo aranbh | nrip bahut bulaai jite asanbh | 16 | 141 |","meaning_en":"","page":266}]},{"type":"heading","kind":"chhand","name":"ਰੂਆਲ ਛੰਦ","gurmukhi":"ਰੂਆਲ ਛੰਦ","roman":"Rooaal chhand","meaning_en":"","page":266},{"type":"verse","number":[1,142],"number_text":"੧। ੧੪੨।","page":266,"lines":[{"gurmukhi":"ਕੋਟਿ ਕੋਟਿ ਬੁਲਾਇ ਰਿਤਜ ਕੋਟਿ ਬ੍ਰਹਮ ਬੁਲਾਇ।","roman":"Koti koti bulaai ritaj koti braham bulaai |","meaning_en":"","page":266},{"gurmukhi":"ਕੋਟਿ ਕੋਟਿ ਬਨਾਇ ਬਿੰਜਨ ਭੋਗੀਅਹਿ ਬਹੁ ਭਾਇ।","roman":"Koti koti banaai binjan bhogeeahi bahu bhaai |","meaning_en":"","page":266},{"gurmukhi":"ਜਤ੍ਰ ਤਤ੍ਰ ਸਮਗ੍ਰਕਾ ਕਹੂੰ ਲਾਗ ਹੈ ਨ੍ਰਿਪਰਾਇ।","roman":"Jatr tatr samgrakaa kahoon laag hai nripraai |","meaning_en":"","page":266},{"gurmukhi":"ਰਾਜਸੂਇ ਕਰਹਿ ਲਗੇ ਸਭ ਧਰਮ ਕੋ ਚਿਤ ਚਾਇ। ੧। ੧੪੨।","roman":"Raajsooi karhi lage sabh dharam ko chit chaai | 1 | 142 |","meaning_en":"","page":266}]},{"type":"verse","number":[2,143],"number_text":"੨। ੧੪੩।","page":266,"lines":[{"gurmukhi":"ਏਕ ਏਕ ਸੁਵਰਨ ਕੋ ਦਿਜ ਏਕ ਦੀਜੈ ਭਾਰ।","roman":"Ek ek suvran ko dij ek deejai bhaar |","meaning_en":"","page":266},{"gurmukhi":"ਏਕ ਸਉ ਗਜ ਏਕ ਸਉ ਰਥਿ ਦੁਇ ਸਹੰਸ੍ਰ ਤੁਖਾਰ।","roman":"Ek sau gaj ek sau rathi dui sahansr tukhaar |","meaning_en":"","page":266},{"gurmukhi":"ਸਹੰਸ ਚਤੁਰ ਸੁਵਰਨ ਸਿੰਗੀ ਮਹਿਖ ਦਾਨ ਅਪਾਰ।","roman":"Sahans chatur suvran singee mahikh daan apaar |","meaning_en":"","page":266},{"gurmukhi":"ਏਕ ਏਕਹਿ ਦੀਜੀਐ ਸੁਨ ਰਾਜ ਰਾਜ ਅਉਤਾਰ। ੨। ੧੪੩।","roman":"Ek ekhi deejeeai sun raaj raaj autaar | 2 | 143 |","meaning_en":"","page":266}]},{"type":"verse","number":[3,144],"number_text":"੩। ੧੪੪।","page":266,"lines":[{"gurmukhi":"ਸੁਵਰਨ ਦਾਨ ਸੁ ਦਾਨ ਰੁਕਮ ਦਾਨ ਸੁ ਤਾਂਬ੍ਰ ਦਾਨ ਅਨੰਤ।","roman":"Suvran daan su daan rukam daan su taanbr daan anant |","meaning_en":"","page":266},{"gurmukhi":"ਅੰਨ ਦਾਨ ਅਨੰਤ ਦੀਜਤ ਦੇਖ ਦੀਨ ਦੁਰੰਤ।","roman":"Ann daan anant deejat dekh deen durant |","meaning_en":"","page":266},{"gurmukhi":"ਬਸਤ੍ਰ ਦਾਨ ਪਟੰਬ੍ਰ ਦਾਨ ਸੁ ਸਸਤ੍ਰ ਦਾਨ ਦਿਜੰਤ।","roman":"Basatr daan patanbr daan su sasatr daan dijant |","meaning_en":"","page":266},{"gurmukhi":"ਭੂਪ ਭਿਛਕ ਹੁਇ ਗਏ ਸਬ ਦੇਸ ਦੇਸ ਦੁਰੰਤ। ੩। ੧੪੪।","roman":"Bhoop bhichhak hui gae sab des des durant | 3 | 144 |","meaning_en":"","page":266}]},{"type":"verse","number":[4,145],"number_text":"੪। ੧੪੫।","page":266,"lines":[{"gurmukhi":"ਚਤ੍ਰ ਕੋਸ ਬਨਾਹਿ ਕੁੰਡਕ ਸਹਸ੍ਰ ਲਾਇ ਪਰਨਾਰ।","roman":"Chatr kos banaahi kundak sahasr laai parnaar |","meaning_en":"","page":266},{"gurmukhi":"ਸਹੰਸ੍ਰ ਹੋਮ ਕਰੈ ਲਗੈ ਦਿਜ ਬੇਦ ਬਿਆਸ ਅਉਤਾਰ।","roman":"Sahansr hom karai lagai dij bed biaas autaar |","meaning_en":"","page":266},{"gurmukhi":"ਹਸਤ ਸੁੰਡ ਪ੍ਰਮਾਨ ਘ੍ਰਿਤ ਕੀ ਪਰਤ ਧਾਰ ਅਪਾਰ।","roman":"Hasat sund pramaan ghrit kee parat dhaar apaar |","meaning_en":"","page":266},{"gurmukhi":"ਹੋਤ ਭਸਮ ਅਨੇਕ ਬਿੰਜਨ ਲਪਟ ਝਪਟ ਕਰਾਲ। ੪। ੧੪੫।","roman":"Hot bhasam anek binjan lapat jhapat karaal | 4 | 145 |","meaning_en":"","page":266}]},{"type":"verse","number":[5,146],"number_text":"੫। ੧੪੬।","page":267,"lines":[{"gurmukhi":"ਮ੍ਰਿਤਕਾ ਸਭ ਤੀਰਥ ਕੀ ਸਭ ਤੀਰਥ ਕੋ ਲੈ ਬਾਰ।","roman":"Mritkaa sabh teerath kee sabh teerath ko lai baar |","meaning_en":"","page":267},{"gurmukhi":"ਕਾਸਟਕਾ ਸਭ ਦੇਸ ਕੀ ਸਭ ਦੇਸ ਕੀ ਜਿਉਨਾਰ।","roman":"Kaasatkaa sabh des kee sabh des kee jiunaar |","meaning_en":"","page":267},{"gurmukhi":"ਭਾਤ ਭਾਤਨ ਕੇ ਮਹਾ ਰਸ ਹੋਮੀਐ ਤਿਹ ਮਾਹਿ।","roman":"Bhaat bhaatan ke mahaa ras homeeai tih maahi |","meaning_en":"","page":267},{"gurmukhi":"ਦੇਖ ਚਕ੍ਰਤ ਰਹੈ ਦਿਜੰਬਰ ਰੀਝ ਹੀ ਨਰ ਨਾਹ। ੫। ੧੪੬।","roman":"Dekh chakrat rahai dijanbar reejh hee nar naah | 5 | 146 |","meaning_en":"","page":267}]},{"type":"verse","number":[6,147],"number_text":"੬। ੧੪੭।","page":267,"lines":[{"gurmukhi":"ਭਾਤ ਭਾਤ ਅਨੇਕ ਬਿਜੰਨ ਹੋਮੀਐ ਤਿਹ ਆਨ।","roman":"Bhaat bhaat anek bijann homeeai tih aan |","meaning_en":"","page":267},{"gurmukhi":"ਚਤੁਰ ਬੇਦ ਪੜੈ ਚਤ੍ਰ ਸਭ ਬਿਪ ਬ੍ਯਾਸ ਸਮਾਨ।","roman":"Chatur bed parai chatr sabh bip byaas samaan |","meaning_en":"","page":267},{"gurmukhi":"ਭਾਤ ਭਾਤ ਅਨੇਕ ਭੂਪਤ ਦੇਤ ਦਾਨ ਅਨੰਤ।","roman":"Bhaat bhaat anek bhoopat det daan anant |","meaning_en":"","page":267},{"gurmukhi":"ਭੂਮ ਭੂਰ ਉਠੀ ਜਯਤ ਧੁਨ ਜਤ੍ਰ ਤਤ੍ਰ ਦੁਰੰਤ। ੬। ੧੪੭।","roman":"Bhoom bhoor uthee jayat dhun jatr tatr durant | 6 | 147 |","meaning_en":"","page":267}]},{"type":"verse","number":[7,148],"number_text":"੭। ੧੪੮।","page":267,"lines":[{"gurmukhi":"ਜੀਤ ਜੀਤ ਮਵਾਸ ਆਸਨ ਅਰਬ ਖਰਬ ਛਿਨਾਇ।","roman":"Jeet jeet mavaas aasan arab kharab chhinaai |","meaning_en":"","page":267},{"gurmukhi":"ਆਨਿ ਆਨਿ ਦੀਏ ਦਿਜਾਨਨ ਜਗ ਮੈ ਕੁਰ ਰਾਇ।","roman":"Aani aani dee'e dijaanan jag mai kur raai |","meaning_en":"","page":267},{"gurmukhi":"ਭਾਤ ਭਾਤ ਅਨੇਕ ਧੂਪ ਸੁ ਧੂਪੀਐ ਤਿਹ ਆਨ।","roman":"Bhaat bhaat anek dhoop su dhoopeeai tih aan |","meaning_en":"","page":267},{"gurmukhi":"ਭਾਤ ਭਾਤ ਉਠੀ ਜਯ ਧੁਨਿ ਜਤ੍ਰ ਤਤ੍ਰ ਦਿਸਾਨ। ੭। ੧੪੮।","roman":"Bhaat bhaat uthee jay dhuni jatr tatr disaan | 7 | 148 |","meaning_en":"","page":267}]},{"type":"verse","number":[8,149],"number_text":"੮। ੧੪੯।","page":267,"lines":[{"gurmukhi":"ਜਰਾਸੰਧਹ ਮਾਰ ਕੈ ਪੁਨਿ ਕੈਰਵਾ ਹਥਿ ਪਾਇ।","roman":"Jaraasandhah maar kai puni kairvaa hathi paai |","meaning_en":"","page":267},{"gurmukhi":"ਰਾਜਸੂਇ ਕੀਓ ਬਡੋ ਮਖਿ ਕਿਸਨ ਕੇ ਮਤਿ ਭਾਇ।","roman":"Raajsooi keeo bado makhi kisan ke mati bhaai |","meaning_en":"","page":267},{"gurmukhi":"ਰਾਜਸੂਇ ਸੁ ਕੈ ਕਿਤੇ ਦਿਨ ਜੀਤ ਸਤ੍ਰੁ ਅਨੰਤ।","roman":"Raajsooi su kai kite din jeet satru anant |","meaning_en":"","page":267},{"gurmukhi":"ਬਾਜਮੇਧ ਅਰੰਭ ਕੀਨੋ ਬੇਦ ਬ੍ਯਾਸ ਮਤੰਤ। ੮। ੧੪੯।","roman":"Baajmedh aranbh keeno bed byaas matant | 8 | 149 |","meaning_en":"","page":267}]}],"ending":{"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਜਗ ਸਮਾਪਤਿਹ।","roman":"Pritham jag samaaptih |","meaning_en":"","page":267}],"page":267}});
